{
  "name": "drag-brasil",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Drag Brasil — jogo de arrancada 3D no navegador (Three.js)",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^7.3.6"
  }
}

:root {
  --bg: #06060a;
  --ink: #f4f1e8;
  --muted: #9a97a8;
  --yellow: #ffd319;
  --orange: #ff5b1a;
  --orange-soft: #ff8a3d;
  --green: #2dff86;
  --red: #ff2e4d;
  --cyan: #37e6ff;
  --panel: rgba(12, 12, 20, 0.78);
  --panel-solid: #0b0b13;
  --line: rgba(255, 255, 255, 0.1);
  --display: "Arial Black", "Helvetica Neue", Impact, system-ui, sans-serif;
  --body: "Helvetica Neue", Arial, system-ui, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  touch-action: none;
}

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(ellipse at 50% 52%, transparent 42%, rgba(0, 0, 0, 0.42) 100%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.28), transparent 22%, transparent 76%, rgba(0, 0, 0, 0.4));
}

#speedlines {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  opacity: 0;
  background: radial-gradient(ellipse at 50% 50%, transparent 34%, rgba(255, 255, 255, 0.05) 72%, rgba(255, 255, 255, 0.12) 100%);
  transition: opacity 0.4s linear;
  mix-blend-mode: screen;
}

.hidden { display: none !important; }

/* ================= generic UI ================= */
.screen {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: flex;
  flex-direction: column;
}

.btn {
  font-family: var(--display);
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border: 0;
  cursor: pointer;
  color: var(--ink);
  background: transparent;
  transition: transform 0.12s ease, filter 0.12s ease, background 0.16s, color 0.16s;
  border-radius: 3px;
}
.btn:active { transform: translateY(1px) scale(0.995); }

.btn-primary {
  background: linear-gradient(180deg, #ffe14a, var(--yellow) 45%, #ffb400);
  color: #171203;
  box-shadow: 0 0 0 1px rgba(255, 240, 180, 0.45), 0 6px 24px rgba(255, 185, 25, 0.28), inset 0 1px 0 #fff7c0;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
}
.btn-primary:hover { filter: brightness(1.08) saturate(1.1); }

.btn-ghost {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.18);
  color: var(--ink);
  backdrop-filter: blur(6px);
}
.btn-ghost:hover { background: rgba(255, 255, 255, 0.12); }

.btn-line {
  border: 1px solid rgba(255, 211, 25, 0.5);
  color: var(--yellow);
  background: rgba(255, 211, 25, 0.06);
}
.btn-line:hover { background: rgba(255, 211, 25, 0.15); }

.btn-big { padding: 20px 46px; font-size: 22px; }
.btn-huge { padding: 22px 40px; font-size: 30px; min-width: 300px; display: flex; align-items: center; justify-content: space-between; gap: 26px; }
.btn-huge .btn-arrow { font-size: 26px; }

.icon-btn {
  width: 44px; height: 44px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 18px; cursor: pointer;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--ink);
}
.icon-btn:hover { background: rgba(255, 255, 255, 0.12); }

.tag {
  font-size: 10px;
  letter-spacing: 0.18em;
  padding: 4px 8px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 2px;
  color: var(--muted);
}
.tag-hot { color: var(--orange); border-color: rgba(255, 91, 26, 0.5); background: rgba(255, 91, 26, 0.1); }

/* ================= boot ================= */
#boot {
  z-index: 60;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at 50% 120%, rgba(255, 91, 26, 0.22), transparent 55%),
    radial-gradient(ellipse at 50% -20%, rgba(55, 230, 255, 0.1), transparent 50%),
    #050508;
  text-align: center;
}
#boot::after {
  content: "";
  position: absolute; inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(0deg, rgba(255,255,255,0.025) 0 1px, transparent 1px 4px);
  opacity: 0.5;
}
.boot-inner { position: relative; z-index: 2; display: flex; flex-direction: column; align-items: center; gap: 16px; padding: 24px; }
.boot-kicker { font-size: 11px; letter-spacing: 0.5em; color: var(--muted); text-transform: uppercase; }
.logo {
  font-family: var(--display);
  font-size: clamp(58px, 11vw, 150px);
  line-height: 0.86;
  letter-spacing: -0.045em;
  color: #fff;
  text-shadow: 0 0 26px rgba(255, 211, 25, 0.25);
  font-style: italic;
  display: flex;
  flex-direction: column;
}
.logo span {
  color: var(--yellow);
  -webkit-text-stroke: 1px rgba(255, 255, 255, 0.06);
  text-shadow: 0 0 36px rgba(255, 91, 26, 0.55);
  font-size: 0.82em;
  letter-spacing: 0.01em;
}
.boot-strip {
  width: min(520px, 70vw); height: 16px; margin: 18px 0 12px;
  background: conic-gradient(from 90deg, #fff 25%, #111 0 50%, #fff 0 75%, #111 0) 0 0 / 16px 16px;
  border-top: 1px solid rgba(255,255,255,0.3);
  border-bottom: 1px solid rgba(255,255,255,0.3);
  opacity: 0.85;
}
.boot-hint { font-size: 12px; color: var(--muted); letter-spacing: 0.06em; margin-top: 6px; }

/* ================= menu ================= */
#menu {
  z-index: 20;
  background:
    linear-gradient(90deg, rgba(4, 4, 9, 0.94) 0%, rgba(4, 4, 9, 0.72) 34%, transparent 66%),
    linear-gradient(180deg, rgba(4, 4, 9, 0.8), transparent 22%, transparent 70%, rgba(4, 4, 9, 0.92));
}
.top-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 22px 34px;
  gap: 16px;
}
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark {
  width: 42px; height: 42px; border-radius: 50%;
  display: grid; place-items: center;
  font-family: var(--display); font-size: 15px; font-weight: 900; color: #171203;
  background: linear-gradient(140deg, #ffe14a, #ffb400 70%);
  box-shadow: 0 0 22px rgba(255, 190, 20, 0.35);
}
.brand-text { font-family: var(--display); font-size: 17px; letter-spacing: 0.04em; line-height: 1; display: flex; flex-direction: column; gap: 4px; }
.brand-text em { font-style: normal; color: var(--yellow); }
.brand-text small { font-family: var(--body); font-size: 8px; letter-spacing: 0.32em; color: var(--muted); font-weight: 600; }
.top-stats { display: flex; align-items: center; gap: 10px; }
.stat-chip {
  border: 1px solid var(--line);
  background: rgba(10, 10, 16, 0.62);
  backdrop-filter: blur(8px);
  padding: 8px 14px; min-width: 96px;
  display: flex; flex-direction: column; gap: 2px;
  border-radius: 4px;
}
.stat-label { font-size: 8px; letter-spacing: 0.2em; color: var(--muted); font-weight: 700; }
.stat-chip strong { font-family: var(--display); font-size: 15px; letter-spacing: 0.02em; }

.menu-main {
  flex: 1; display: flex; align-items: center; justify-content: space-between;
  gap: 32px; padding: 10px 34px 20px;
}
.menu-copy { max-width: 560px; }
.eyebrow { font-size: 10px; letter-spacing: 0.34em; color: var(--orange-soft); font-weight: 700; margin-bottom: 18px; }
.menu-title {
  font-family: var(--display);
  font-size: clamp(38px, 5.5vw, 76px);
  line-height: 0.92;
  letter-spacing: -0.035em;
  text-transform: uppercase;
  font-style: italic;
  text-shadow: 0 8px 40px rgba(0,0,0,0.5);
}
.menu-title .stroke {
  color: transparent;
  -webkit-text-stroke: 1.5px var(--yellow);
  text-shadow: 0 0 40px rgba(255, 211, 25, 0.2);
}
.menu-sub { margin: 20px 0 28px; max-width: 430px; color: #b9b6c4; font-size: 14px; line-height: 1.55; }
.menu-actions { display: flex; align-items: stretch; gap: 12px; flex-wrap: wrap; }
.menu-actions .btn-ghost { padding: 0 22px; font-size: 13px; }

.menu-side { display: flex; flex-direction: column; gap: 12px; width: 330px; }
.card {
  background: rgba(9, 9, 15, 0.66);
  border: 1px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(12px);
  padding: 18px;
  border-radius: 4px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.35);
}
.card-top { display: flex; justify-content: space-between; align-items: center; font-size: 9px; letter-spacing: 0.22em; color: var(--muted); font-weight: 700; margin-bottom: 10px; }
.card h3 { font-family: var(--display); font-size: 24px; letter-spacing: 0.01em; text-transform: uppercase; }
.car-mini-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 16px 0 18px; }
.car-mini-stats div { border-left: 2px solid rgba(255, 211, 25, 0.5); padding-left: 8px; }
.car-mini-stats b { display: block; font-family: var(--display); font-size: 16px; }
.car-mini-stats small { font-size: 8px; letter-spacing: 0.14em; color: var(--muted); }
.car-card .btn { width: 100%; padding: 12px; font-size: 11px; }
.next-card p { color: #b9b6c4; font-size: 12.5px; line-height: 1.5; margin: 10px 0 14px; font-style: italic; }
.rival-meta { display: flex; align-items: center; gap: 8px; font-size: 9px; letter-spacing: 0.12em; color: var(--muted); font-weight: 700; }
.rival-meta .dot { width: 3px; height: 3px; border-radius: 50%; background: var(--orange); }

.menu-foot {
  display: flex; justify-content: space-between; gap: 20px;
  padding: 14px 34px 18px;
  font-size: 10px; letter-spacing: 0.05em; color: #6b6878;
  border-top: 1px solid rgba(255,255,255,0.06);
}
.menu-foot b { color: var(--yellow); }
.foot-right { text-align: right; }

/* ================= garage / help ================= */
#garage, #help {
  z-index: 30;
  background:
    linear-gradient(90deg, rgba(4, 4, 9, 0.96), rgba(4, 4, 9, 0.86) 60%, rgba(4, 4, 9, 0.6)),
    radial-gradient(ellipse at 78% 45%, rgba(255, 120, 20, 0.12), transparent 50%);
}
.panel-head {
  display: flex; align-items: center; gap: 22px;
  padding: 20px 34px; border-bottom: 1px solid rgba(255,255,255,0.08);
}
.panel-head h2 { font-family: var(--display); font-size: 26px; letter-spacing: 0.02em; }
.panel-head h2 span { color: var(--yellow); }
.btn-back { font-size: 11px; padding: 10px 16px; background: rgba(255,255,255,0.05); border: 1px solid var(--line); }
.wallet { margin-left: auto; font-family: var(--display); font-size: 17px; color: var(--yellow); letter-spacing: 0.04em; }
.garage-body { flex: 1; overflow: auto; display: grid; grid-template-columns: 1.15fr 0.85fr; gap: 26px; padding: 22px 34px 30px; }
.section-label { font-size: 10px; letter-spacing: 0.26em; color: var(--muted); font-weight: 700; margin: 4px 0 10px; }
.car-list { display: flex; flex-direction: column; gap: 8px; margin-bottom: 22px; }
.car-row {
  display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 10px;
  padding: 12px 16px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.03);
  cursor: pointer;
  border-radius: 3px;
  transition: background 0.15s, border-color 0.15s;
}
.car-row:hover { background: rgba(255,255,255,0.07); }
.car-row.active { border-color: var(--yellow); background: rgba(255, 211, 25, 0.08); }
.car-row.locked { opacity: 0.75; }
.car-row h4 { font-family: var(--display); font-size: 16px; letter-spacing: 0.02em; }
.car-row .spec { font-size: 10px; color: var(--muted); margin-top: 4px; letter-spacing: 0.03em; }
.car-row .car-action { font-size: 10px; font-weight: 800; letter-spacing: 0.1em; }
.car-row .car-action.buy { color: var(--green); }
.car-row .car-action.equipped { color: var(--yellow); }

.paint-list { display: flex; flex-wrap: wrap; gap: 10px; }
.paint-swatch {
  width: 42px; height: 42px; border-radius: 50%;
  border: 2px solid rgba(255,255,255,0.15);
  cursor: pointer; position: relative;
  box-shadow: inset 0 -8px 16px rgba(0,0,0,0.45), inset 0 6px 12px rgba(255,255,255,0.25);
  transition: transform 0.12s;
}
.paint-swatch:hover { transform: scale(1.08); }
.paint-swatch.active { border-color: #fff; box-shadow: 0 0 0 3px rgba(255, 211, 25, 0.4); }
.paint-swatch.active::after { content: "✓"; position: absolute; inset: 0; display: grid; place-items: center; font-size: 15px; color: #fff; text-shadow: 0 1px 4px #000; }

.upgrade-list { display: flex; flex-direction: column; gap: 10px; }
.upgrade-row {
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.03);
  padding: 12px 14px;
  border-radius: 3px;
}
.upgrade-head { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.upgrade-head h4 { font-family: var(--display); font-size: 13px; letter-spacing: 0.08em; }
.upgrade-head .lvl { font-size: 10px; color: var(--muted); letter-spacing: 0.08em; }
.pips { display: flex; gap: 4px; margin: 8px 0 10px; }
.pips i { height: 5px; flex: 1; background: rgba(255,255,255,0.1); border-radius: 1px; }
.pips i.on { background: linear-gradient(90deg, var(--orange), var(--yellow)); box-shadow: 0 0 8px rgba(255, 180, 30, 0.4); }
.upgrade-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.upgrade-desc { font-size: 10px; color: var(--muted); }
.upgrade-btn { font-family: var(--display); font-size: 10px; letter-spacing: 0.08em; padding: 8px 12px; border-radius: 2px; background: rgba(255, 211, 25, 0.1); border: 1px solid rgba(255, 211, 25, 0.35); color: var(--yellow); cursor: pointer; }
.upgrade-btn:hover { background: rgba(255, 211, 25, 0.2); }
.upgrade-btn:disabled { opacity: 0.35; cursor: not-allowed; }
.upgrade-btn.max { border-color: var(--line); color: var(--muted); background: transparent; }
.upgrade-note { font-size: 10px; color: #6b6878; line-height: 1.6; margin-top: 14px; }

.help-body { flex: 1; overflow: auto; padding: 26px 34px 34px; }
.help-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
.help-card { border: 1px solid var(--line); background: rgba(10,10,16,0.6); padding: 18px; border-radius: 3px; position: relative; }
.help-num { font-family: var(--display); font-size: 34px; color: rgba(255, 211, 25, 0.18); line-height: 1; margin-bottom: 10px; }
.help-card h3 { font-family: var(--display); font-size: 14px; letter-spacing: 0.06em; margin-bottom: 10px; }
.help-card p { font-size: 12px; line-height: 1.6; color: #b0adbc; }
.keyrow { margin-top: 14px; display: flex; align-items: center; flex-wrap: wrap; gap: 6px; font-size: 10px; color: var(--muted); }
kbd { display: inline-block; padding: 3px 7px; border: 1px solid rgba(255,255,255,0.2); border-bottom-width: 2px; border-radius: 3px; font-family: var(--body); font-size: 9px; color: var(--ink); background: rgba(255,255,255,0.06); }
.tree-mini { margin-top: 16px; display: flex; gap: 5px; align-items: center; }
.tree-mini i { width: 12px; height: 12px; border-radius: 50%; background: rgba(255, 170, 20, 0.2); border: 1px solid rgba(255, 170, 20, 0.35); }
.tree-mini i:last-of-type { background: rgba(255,255,255,0.1); }
.tree-mini b { width: 14px; height: 14px; border-radius: 50%; background: var(--green); box-shadow: 0 0 12px var(--green); }
.help-tip { margin-top: 18px; font-size: 12px; color: #b0adbc; border-left: 2px solid var(--orange); padding-left: 12px; }

/* ================= HUD ================= */
#hud { z-index: 15; pointer-events: none; }
#hud .hud-top {
  display: flex; justify-content: space-between; align-items: flex-start;
  padding: 18px 24px 0; gap: 16px;
}
.hud-rival { display: flex; flex-direction: column; gap: 4px; min-width: 170px; text-shadow: 0 2px 8px #000; }
.hud-rival .lbl { font-size: 8px; letter-spacing: 0.24em; color: var(--muted); font-weight: 700; }
.hud-rival strong { font-family: var(--display); font-size: 16px; letter-spacing: 0.02em; color: #e9e6f0; }
.hud-right { display: flex; align-items: center; gap: 12px; }
.hud-icon { pointer-events: auto; background: rgba(8,8,14,0.55); backdrop-filter: blur(8px); }
.hud-distance { text-align: right; font-family: var(--display); text-shadow: 0 2px 8px #000; display: flex; flex-direction: column; }
.hud-distance span { font-size: 18px; color: var(--yellow); }
.hud-distance small { font-size: 8px; letter-spacing: 0.2em; color: var(--muted); }

.tree-hud {
  position: absolute; left: 50%; transform: translateX(-50%); top: 10px;
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  background: linear-gradient(180deg, rgba(7,7,12,0.86), rgba(7,7,12,0.5));
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 6px;
  padding: 10px 18px 8px;
  backdrop-filter: blur(10px);
  min-width: 190px;
}
.tree-lights { display: flex; gap: 9px; align-items: center; }
.tree-lights i {
  width: 17px; height: 17px; border-radius: 50%;
  background: #1a1a20;
  border: 1px solid rgba(255,255,255,0.08);
  box-shadow: inset 0 2px 3px rgba(0,0,0,0.8);
  transition: background 0.08s, box-shadow 0.08s;
}
.tree-lights .t-amber { --c: #ffae1a; }
.tree-lights .t-green { --c: #2dff86; width: 22px; height: 22px; }
.tree-lights .t-red { --c: #ff2e4d; width: 13px; height: 13px; }
.tree-lights i.on { background: var(--c); box-shadow: 0 0 14px var(--c), 0 0 32px var(--c); }
.tree-timer { font-family: var(--display); font-size: 26px; letter-spacing: 0.03em; line-height: 1; color: #fff; font-variant-numeric: tabular-nums; }
.tree-phase { font-size: 8px; letter-spacing: 0.28em; color: var(--muted); font-weight: 700; }

.gapbar {
  position: absolute; left: 50%; transform: translateX(-50%); top: 104px;
  width: min(560px, 72vw);
  display: flex; align-items: center; gap: 10px;
}
.gapbar-label { font-size: 8px; letter-spacing: 0.16em; font-weight: 800; color: var(--muted); text-shadow: 0 1px 4px #000; width: 38px; }
.gapbar-label.right { text-align: right; }
.gap-track { position: relative; flex: 1; height: 4px; background: rgba(255,255,255,0.14); border-radius: 2px; }
.gap-finish { position: absolute; right: -10px; top: 50%; transform: translateY(-50%); font-size: 13px; }
.gap-car { position: absolute; top: 50%; width: 16px; height: 8px; margin-top: -4px; border-radius: 2px; transition: left 0.08s linear; }
.gap-car.you { background: var(--yellow); box-shadow: 0 0 10px rgba(255, 211, 25, 0.8); }
.gap-car.rival { background: var(--red); box-shadow: 0 0 10px rgba(255, 46, 77, 0.7); margin-top: 3px; }

.launch-prompt { position: absolute; left: 50%; top: 38%; transform: translate(-50%, -50%); text-align: center; animation: pulsePrompt 0.7s infinite alternate; pointer-events: none; }
.lp-line { font-size: 10px; letter-spacing: 0.3em; color: var(--green); font-weight: 800; }
.lp-big { font-family: var(--display); font-style: italic; font-size: clamp(42px, 7vw, 78px); color: #fff; text-shadow: 0 0 30px rgba(45, 255, 134, 0.7), 0 4px 0 #0b3a22; line-height: 1; }
@keyframes pulsePrompt { from { opacity: 0.45; transform: translate(-50%, -50%) scale(0.98); } to { opacity: 1; transform: translate(-50%, -50%) scale(1.02); } }

.hud-toast {
  position: absolute; left: 50%; top: 46%; transform: translateX(-50%);
  font-family: var(--display); font-size: 26px; letter-spacing: 0.06em;
  color: var(--yellow); text-shadow: 0 0 24px rgba(255, 150, 20, 0.6), 0 2px 10px #000;
  opacity: 0; transition: opacity 0.2s; text-align: center; white-space: nowrap;
}
.hud-toast.show { opacity: 1; }

.hud-bottom {
  position: absolute; left: 0; right: 0; bottom: 0;
  display: flex; align-items: flex-end; justify-content: space-between;
  gap: 18px;
  padding: 0 24px calc(18px + env(safe-area-inset-bottom));
}
.steer-side { display: flex; flex-direction: column; align-items: center; gap: 6px; pointer-events: auto; }
.wheel-pad {
  position: relative;
  width: 132px; height: 132px;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 45%, rgba(255,255,255,0.09), rgba(7,7,12,0.7) 65%);
  border: 1px solid rgba(255,255,255,0.16);
  box-shadow: 0 8px 30px rgba(0,0,0,0.5), inset 0 0 30px rgba(0,0,0,0.6);
  touch-action: none;
  cursor: grab;
}
.wheel-pad:active { cursor: grabbing; }
.wheel-ring { position: absolute; inset: 9px; border-radius: 50%; border: 8px solid #22222c; box-shadow: inset 0 0 0 1px rgba(255,255,255,0.12), 0 0 0 1px rgba(0,0,0,0.6); }
.wheel-spoke { position: absolute; left: 50%; top: 50%; width: 5px; height: 44px; background: linear-gradient(#3a3a48, #202028); transform-origin: 50% 0; margin-left: -2.5px; border-radius: 2px; }
.wheel-spoke.s1 { transform: rotate(0deg) translateY(10px); }
.wheel-spoke.s2 { transform: rotate(120deg) translateY(10px); }
.wheel-spoke.s3 { transform: rotate(240deg) translateY(10px); }
.wheel-knob { position: absolute; left: 50%; top: 50%; width: 26px; height: 26px; margin: -13px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #ffd319, #ff8a1a 60%, #b34a00); box-shadow: 0 0 12px rgba(255, 150, 20, 0.5); }
.wheel-cap { position: absolute; left: 50%; top: 50%; width: 34px; height: 34px; margin: -17px; border-radius: 50%; border: 1px solid rgba(255,255,255,0.1); }
.steer-label { font-size: 8px; letter-spacing: 0.26em; color: var(--muted); font-weight: 700; text-shadow: 0 1px 4px #000; }

.cluster { display: flex; flex-direction: column; align-items: center; gap: 5px; padding-bottom: 4px; min-width: 220px; }
.speed-row { display: flex; align-items: baseline; gap: 7px; line-height: 0.82; }
.speed-row span { font-family: var(--display); font-style: italic; font-size: 66px; letter-spacing: -0.03em; color: #fff; text-shadow: 0 4px 20px rgba(0,0,0,0.8); font-variant-numeric: tabular-nums; }
.speed-row em { font-style: normal; font-size: 10px; letter-spacing: 0.14em; color: var(--muted); font-weight: 700; }
.rpm-strip { width: 220px; height: 8px; background: rgba(255,255,255,0.12); border-radius: 2px; position: relative; overflow: hidden; }
.rpm-fill { position: absolute; left: 0; top: 0; bottom: 0; width: 0%; background: linear-gradient(90deg, #37e6ff, #ffd319 62%, #ff5b1a); border-radius: 2px; transition: width 0.05s linear; }
.rpm-red { position: absolute; right: 0; top: 0; bottom: 0; width: 14%; background: repeating-linear-gradient(45deg, rgba(255,46,77,0.8) 0 4px, rgba(255,46,77,0.2) 4px 8px); }
.gear-row { display: flex; align-items: center; gap: 8px; }
.gear-lbl { font-size: 7px; letter-spacing: 0.22em; color: var(--muted); font-weight: 700; }
.gear-num { font-family: var(--display); font-size: 22px; color: var(--yellow); min-width: 22px; text-align: center; text-shadow: 0 0 16px rgba(255, 200, 30, 0.4); }
.gear-hint { font-size: 7px; letter-spacing: 0.18em; color: #6b6878; font-weight: 700; }

.pedal-side { display: flex; flex-direction: column; align-items: flex-end; gap: 10px; pointer-events: auto; }
.shift-pair { display: flex; gap: 8px; }
.shift-btn {
  width: 54px; height: 44px;
  border-radius: 4px;
  border: 1px solid rgba(255,255,255,0.2);
  background: rgba(10,10,16,0.72);
  color: var(--ink);
  font-size: 15px;
  cursor: pointer;
  backdrop-filter: blur(6px);
}
.shift-btn:active { background: rgba(255,211,25,0.25); }
.pedal-row { display: flex; align-items: flex-end; gap: 10px; }
.pedal {
  font-family: var(--display);
  font-size: 12px;
  letter-spacing: 0.06em;
  color: #fff;
  border: 1px solid rgba(255,255,255,0.25);
  cursor: pointer;
  border-radius: 50%;
  box-shadow: 0 10px 30px rgba(0,0,0,0.45), inset 0 -8px 0 rgba(0,0,0,0.28);
  transition: transform 0.05s, filter 0.05s, box-shadow 0.05s;
  touch-action: none;
}
.pedal.gas {
  width: 118px; height: 118px;
  background: radial-gradient(circle at 50% 38%, #37ff9a, #0fbf62 60%, #067a3e);
  border-color: rgba(120, 255, 180, 0.55);
  text-shadow: 0 1px 2px rgba(0,0,0,0.5);
}
.pedal.brake {
  width: 82px; height: 82px;
  background: radial-gradient(circle at 50% 38%, #ff6b7f, #d81432 60%, #7d0719);
  border-color: rgba(255, 120, 140, 0.5);
}
.pedal.active { transform: translateY(3px) scale(0.97); filter: brightness(1.25); box-shadow: 0 2px 14px rgba(0,0,0,0.6), inset 0 -4px 0 rgba(0,0,0,0.3); }

.foul-banner {
  position: absolute; left: 50%; top: 33%; transform: translate(-50%, -50%) rotate(-3deg);
  font-family: var(--display); font-style: italic; font-size: clamp(30px, 5.5vw, 58px);
  color: #ff2e4d; text-shadow: 0 0 30px rgba(255, 20, 60, 0.7), 0 3px 0 #4d000c;
  border: 3px solid #ff2e4d; padding: 10px 24px; letter-spacing: 0.04em;
  background: rgba(20,0,5,0.55);
}

/* ================= results ================= */
#results {
  z-index: 40;
  align-items: center; justify-content: center;
  background: radial-gradient(ellipse at 50% 45%, rgba(10,10,18,0.6), rgba(3,3,7,0.92));
  backdrop-filter: blur(8px);
}
.results-card {
  width: min(680px, 92vw);
  background: linear-gradient(180deg, rgba(16,16,26,0.96), rgba(8,8,14,0.98));
  border: 1px solid rgba(255,255,255,0.14);
  border-top: 3px solid var(--yellow);
  padding: 30px 34px 28px;
  box-shadow: 0 40px 120px rgba(0,0,0,0.7);
  animation: cardIn 0.35s cubic-bezier(0.2, 1, 0.3, 1);
}
@keyframes cardIn { from { transform: translateY(20px) scale(0.97); opacity: 0; } to { transform: none; opacity: 1; } }
.results-kicker { font-size: 9px; letter-spacing: 0.32em; color: var(--muted); font-weight: 700; }
#res-title { font-family: var(--display); font-style: italic; font-size: clamp(46px, 8vw, 76px); line-height: 1; letter-spacing: -0.02em; margin: 8px 0 4px; color: var(--yellow); text-shadow: 0 0 40px rgba(255, 200, 30, 0.35); }
#results.lose #res-title { color: #ff5b6e; text-shadow: 0 0 40px rgba(255, 40, 70, 0.3); }
.res-sub { font-size: 12px; color: #b0adbc; margin-bottom: 22px; }
.res-times { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 12px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 16px 0; }
.res-times > div { display: flex; flex-direction: column; gap: 4px; }
.res-big span { font-family: var(--display); font-size: 40px; color: #fff; line-height: 1; font-variant-numeric: tabular-nums; }
.res-col span { font-family: var(--display); font-size: 18px; color: #e9e6f0; padding-top: 12px; font-variant-numeric: tabular-nums; }
.res-times small { font-size: 8px; letter-spacing: 0.2em; color: var(--muted); font-weight: 700; }
.res-money { display: flex; align-items: center; justify-content: space-between; padding: 16px 0; }
.res-money span { font-size: 9px; letter-spacing: 0.24em; color: var(--muted); font-weight: 700; }
.res-money strong { font-family: var(--display); font-size: 26px; color: var(--green); }
.res-buttons { display: flex; gap: 10px; flex-wrap: wrap; }
.res-buttons .btn-primary { flex: 1; padding: 15px; font-size: 14px; }
.res-buttons .btn-ghost, .res-buttons .btn-line { padding: 15px 20px; font-size: 11px; }
.res-record { margin-top: 16px; font-size: 11px; letter-spacing: 0.14em; color: var(--yellow); border: 1px solid rgba(255,211,25,0.4); padding: 8px 12px; text-align: center; background: rgba(255,211,25,0.08); }

#rotate-hint { position: fixed; bottom: 10px; left: 50%; transform: translateX(-50%); z-index: 70; font-size: 11px; color: var(--muted); background: rgba(0,0,0,0.6); padding: 8px 14px; border-radius: 20px; }

#debug-perf { position: fixed; left: 8px; top: 8px; z-index: 90; font: 10px/1.4 monospace; color: #0f0; background: rgba(0,0,0,0.7); padding: 6px 8px; white-space: pre; }

/* ================= responsive ================= */
@media (max-width: 980px) {
  .menu-side { width: 280px; }
  .menu-title { font-size: clamp(34px, 6.4vw, 60px); }
  .help-grid { grid-template-columns: repeat(2, 1fr); }
  .garage-body { grid-template-columns: 1fr; }
  .top-stats .stat-chip:nth-child(3) { display: none; }
}

@media (max-width: 720px) {
  .top-bar { padding: 14px 16px; }
  .top-stats .stat-chip { min-width: 0; padding: 6px 9px; }
  .stat-chip strong { font-size: 12px; }
  .brand-text small { display: none; }
  .menu-main { flex-direction: column; align-items: flex-start; justify-content: center; padding: 0 18px; gap: 16px; }
  .menu-copy { max-width: 100%; }
  .menu-title { font-size: clamp(30px, 8.4vw, 46px); }
  .menu-sub { display: none; }
  .menu-actions { gap: 8px; }
  .btn-huge { min-width: 0; width: 100%; font-size: 22px; padding: 16px 22px; }
  .menu-side { width: 100%; flex-direction: row; }
  .menu-side .next-card { display: none; }
  .menu-side .car-card { flex: 1; padding: 12px 14px; }
  .car-mini-stats { margin: 10px 0 12px; }
  .menu-foot { display: none; }
  .panel-head { padding: 12px 16px; gap: 10px; }
  .panel-head h2 { font-size: 18px; }
  .garage-body, .help-body { padding: 16px; }
  .help-grid { grid-template-columns: 1fr; }
  .hud-bottom { padding: 0 12px calc(12px + env(safe-area-inset-bottom)); gap: 8px; }
  .wheel-pad { width: 108px; height: 108px; }
  .pedal.gas { width: 96px; height: 96px; font-size: 10px; }
  .pedal.brake { width: 68px; height: 68px; font-size: 9px; }
  .shift-btn { width: 46px; height: 38px; }
