import { DragSim, QUARTER_MILE } from './src/physics.js';
import { CARS, buildSpec } from './src/data.js';

function run(car, upgrades, revTo) {
  const spec = buildSpec(car, upgrades);
  const sim = new DragSim(spec);
  const dt = 1/120;
  sim.clutch = true; sim.prevClutch = true;
  // rev to target
  let guard = 0;
  while (sim.engineRpm < revTo && guard++ < 1000) sim.step(dt, { throttle: 1, clutch: true }, true);
  // hold a moment
  for (let i=0;i<20;i++) sim.step(dt, { throttle: 1, clutch: true }, true);
  const t0 = sim.time;
  let launchRpm = sim.engineRpm;
  let steps = 0;
  while (sim.distance < QUARTER_MILE && steps < 120*25) {
    sim.step(dt, { throttle: 1, clutch: false }, false);
    sim.autoShift();
    steps++;
  }
  return { et: sim.time - t0, trap: sim.speed*3.6, launchRpm, gear: sim.gear, dist: sim.distance };
}

