import * as THREE from "three";

const cache = new Map();

export function canvasTex(key, w, h, draw, opts = {}) {
  if (cache.has(key)) return cache.get(key);
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  const ctx = c.getContext("2d");
  draw(ctx, w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 8;
  if (opts.repeat) {
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(opts.repeat[0], opts.repeat[1]);
  }
  cache.set(key, t);
  return t;
}

export function asphaltTexture() {
  return canvasTex("asphalt", 512, 512, (ctx, w, h) => {
    ctx.fillStyle = "#1a1a20";
    ctx.fillRect(0, 0, w, h);
    const img = ctx.getImageData(0, 0, w, h);
    const d = img.data;
    for (let i = 0; i < d.length; i += 4) {
      const n = (Math.random() - 0.5) * 34;
      d[i] += n;
      d[i + 1] += n;
      d[i + 2] += n + 2;
    }
    ctx.putImageData(img, 0, 0);
    // agregado graúdo
    for (let i = 0; i < 900; i++) {
      const g = 30 + Math.random() * 50;
      ctx.fillStyle = `rgba(${g},${g},${g + 4},${0.25 + Math.random() * 0.4})`;
      ctx.beginPath();
      ctx.arc(Math.random() * w, Math.random() * h, 0.6 + Math.random() * 1.7, 0, 7);
      ctx.fill();
    }
    // marcas de borracha
    for (let i = 0; i < 22; i++) {
      ctx.strokeStyle = `rgba(0,0,0,${0.05 + Math.random() * 0.15})`;
      ctx.lineWidth = 2 + Math.random() * 9;
      const x = Math.random() * w;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.bezierCurveTo(x + 20, h * 0.3, x - 30, h * 0.6, x + 10, h);
      ctx.stroke();
    }
    // emendas
    ctx.strokeStyle = "rgba(0,0,0,0.25)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, h * 0.5);
    ctx.lineTo(w, h * 0.5);
    ctx.stroke();
  }, { repeat: [4, 90] });
}

export function checkerTexture() {
  return canvasTex("checker", 256, 64, (ctx, w, h) => {
    const s = 32;
    for (let y = 0; y < h; y += s) {
      for (let x = 0; x < w; x += s) {
        ctx.fillStyle = ((x / s + y / s) | 0) % 2 === 0 ? "#f2f0e8" : "#101014";
        ctx.fillRect(x, y, s, s);
      }
    }
  });
}

export function bannerTexture(text, bg = "#0b0b12", fg = "#ffd319", accent = "#ff5a12") {
  return canvasTex(`banner:${text}:${bg}:${fg}`, 512, 128, (ctx, w, h) => {
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = accent;
    ctx.fillRect(0, 0, 14, h);
    ctx.fillRect(w - 14, 0, 14, h);
    ctx.strokeStyle = "rgba(255,255,255,0.15)";
    ctx.lineWidth = 3;
    ctx.strokeRect(8, 8, w - 16, h - 16);
    ctx.fillStyle = fg;
    ctx.font = "italic 900 62px Arial, Helvetica, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(text, w / 2, h / 2 + 4);
  });
}

export function signTexture(text, sub = "") {
  return canvasTex(`sign:${text}:${sub}`, 256, 256, (ctx, w, h) => {
    ctx.fillStyle = "#0c0c12";
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = "#ffd319";
    ctx.lineWidth = 8;
    ctx.strokeRect(10, 10, w - 20, h - 20);
    ctx.fillStyle = "#ffd319";
    ctx.font = "italic 900 84px Arial, Helvetica, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(text, w / 2, h / 2 - 24);
    ctx.fillStyle = "#cfcdd6";
    ctx.font = "700 26px Arial, Helvetica, sans-serif";
    ctx.fillText(sub, w / 2, h / 2 + 52);
  });
}

export function windowsTexture() {
  return canvasTex("windows", 128, 256, (ctx, w, h) => {
    ctx.fillStyle = "#070810";
    ctx.fillRect(0, 0, w, h);
    const cols = 10;
    const rows = 22;
    const cw = w / cols;
    const ch = h / rows;
    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        if (Math.random() < 0.28) {
          const warm = Math.random() < 0.7;
          ctx.fillStyle = warm
            ? `rgba(255,${180 + Math.random() * 50},${90 + Math.random() * 60},${0.35 + Math.random() * 0.5})`
            : `rgba(120,200,255,${0.25 + Math.random() * 0.4})`;
          ctx.fillRect(x * cw + cw * 0.18, y * ch + ch * 0.22, cw * 0.58, ch * 0.48);
        }
      }
    }
  }, { repeat: [1, 1] });
}

export function glowTexture() {
  return canvasTex("glow", 128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 2, w / 2, h / 2, w / 2);
    g.addColorStop(0, "rgba(255,255,255,1)");
    g.addColorStop(0.18, "rgba(255,255,255,0.75)");
    g.addColorStop(0.45, "rgba(255,255,255,0.22)");
    g.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

export function smokeTexture() {
  return canvasTex("smoke", 128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 4, w / 2, h / 2, w / 2);
    g.addColorStop(0, "rgba(255,255,255,0.85)");
    g.addColorStop(0.35, "rgba(235,235,245,0.45)");
    g.addColorStop(0.7, "rgba(200,200,215,0.12)");
    g.addColorStop(1, "rgba(190,190,210,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

export function lightPoolTexture() {
  return canvasTex("pool", 256, 256, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 4, w / 2, h / 2, w / 2);
    g.addColorStop(0, "rgba(255,240,200,0.55)");
    g.addColorStop(0.4, "rgba(255,220,160,0.2)");
    g.addColorStop(1, "rgba(255,210,150,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

export function crowdTexture() {
  return canvasTex("crowd", 256, 64, (ctx, w, h) => {
    ctx.fillStyle = "#07070c";
    ctx.fillRect(0, 0, w, h);
    const colors = ["#ffd319", "#ff5a12", "#2dff86", "#37e6ff", "#ff2e4d", "#e8e6df", "#8c2bff"];
    for (let i = 0; i < 420; i++) {
      ctx.fillStyle = colors[(Math.random() * colors.length) | 0];
      ctx.globalAlpha = 0.25 + Math.random() * 0.5;
      const r = 1.5 + Math.random() * 2.5;
      ctx.beginPath();
      ctx.arc(Math.random() * w, Math.random() * h, r, 0, 7);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }, { repeat: [6, 1] });
}

import * as THREE from "three";
import { RoundedBoxGeometry } from "three/addons/geometries/RoundedBoxGeometry.js";
import { glowTexture } from "./textures.js";

const PAINT_CACHE = new Map();

function paintMaterial(hex) {
  return new THREE.MeshPhysicalMaterial({
    color: new THREE.Color(hex),
    metalness: 0.62,
    roughness: 0.27,
    clearcoat: 1,
    clearcoatRoughness: 0.09,
    envMapIntensity: 1.35,
  });
}

const mats = {
  dark: new THREE.MeshStandardMaterial({ color: 0x0b0b0f, roughness: 0.7, metalness: 0.3 }),
  trim: new THREE.MeshStandardMaterial({ color: 0x17171d, roughness: 0.45, metalness: 0.7 }),
  chrome: new THREE.MeshStandardMaterial({ color: 0xc9ccd6, roughness: 0.18, metalness: 1 }),
  tire: new THREE.MeshStandardMaterial({ color: 0x0a0a0c, roughness: 0.95, metalness: 0 }),
  rim: new THREE.MeshStandardMaterial({ color: 0x9a9eaa, roughness: 0.3, metalness: 0.95 }),
  rimDark: new THREE.MeshStandardMaterial({ color: 0x363a44, roughness: 0.4, metalness: 0.8 }),
  glass: new THREE.MeshPhysicalMaterial({
    color: 0x0b1420,
    metalness: 0.1,
    roughness: 0.06,
    transparent: true,
    opacity: 0.32,
    side: THREE.DoubleSide,
    depthWrite: false,
    envMapIntensity: 1.6,
  }),
  interior: new THREE.MeshStandardMaterial({ color: 0x141318, roughness: 0.85, metalness: 0.1 }),
  seat: new THREE.MeshStandardMaterial({ color: 0x241b1d, roughness: 0.9 }),
  seatRed: new THREE.MeshStandardMaterial({ color: 0x5c1620, roughness: 0.8 }),
  headlight: new THREE.MeshStandardMaterial({ color: 0xfff6d8, emissive: 0xfff0c0, emissiveIntensity: 4, roughness: 0.2 }),
  taillight: new THREE.MeshStandardMaterial({ color: 0x420008, emissive: 0xff1020, emissiveIntensity: 0.9, roughness: 0.25 }),
  amber: new THREE.MeshStandardMaterial({ color: 0x3a1b00, emissive: 0xff8a00, emissiveIntensity: 1.2, roughness: 0.3 }),
};

function mesh(geo, mat, parent, cast = true) {
  const m = new THREE.Mesh(geo, mat);
  m.castShadow = cast;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

function wheel(x, z, side, front) {
  const g = new THREE.Group();
  g.position.set(x, 0.345, z);
  const steerGroup = new THREE.Group();
  const spin = new THREE.Group();
  g.add(steerGroup);
  steerGroup.add(spin);

  const r = 0.345;
  const width = 0.29;
  const tireGeo = new THREE.CylinderGeometry(r, r, width, 28, 1);
  tireGeo.rotateZ(Math.PI / 2);
  mesh(tireGeo, mats.tire, spin);

  // sulcos
  const groove = new THREE.MeshStandardMaterial({ color: 0x1d1d22, roughness: 0.9 });
  for (let i = -2; i <= 2; i++) {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(r * 0.9, 0.012, 6, 36), groove);
    ring.rotation.y = Math.PI / 2;
    ring.position.x = i * 0.055;
    spin.add(ring);
  }

  const rimGeo = new THREE.CylinderGeometry(r * 0.63, r * 0.63, width + 0.02, 24);
  rimGeo.rotateZ(Math.PI / 2);
  mesh(rimGeo, mats.rimDark, spin, false);
  const face = new THREE.CylinderGeometry(r * 0.64, r * 0.64, 0.03, 24);
  face.rotateZ(Math.PI / 2);
  const faceMesh = mesh(face, mats.rim, spin, false);
  faceMesh.position.x = side * (width / 2 + 0.005);

  // raios
  const spokeMat = mats.rim;
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2;
    const sp = new THREE.Mesh(new THREE.BoxGeometry(0.035, r * 1.1, 0.075), spokeMat);
    sp.position.set(side * (width / 2 + 0.03), Math.sin(a) * 0.02, 0);
    sp.rotation.x = a;
    spin.add(sp);
  }
  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 0.04, 16), mats.chrome);
  cap.rotation.z = Math.PI / 2;
  cap.position.x = side * (width / 2 + 0.02);
  spin.add(cap);

  // pinça de freio
  const caliper = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.16, 0.1), new THREE.MeshStandardMaterial({ color: 0xff4a12, roughness: 0.4, metalness: 0.4 }));
  caliper.position.set(side * 0.02, 0.16, 0.08);
  steerGroup.add(caliper);

  return { group: g, steerGroup, spin, side, front };
}

/**
 * Constrói um carro low-poly estilizado. Frente = +Z, largura = X.
 */
export function createCarModel({ paint = "#ff5a12", interior = false, plate = "DB" } = {}) {
  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  const paintMat = paintMaterial(paint);
  const paintDark = new THREE.MeshStandardMaterial({ color: 0x08080b, roughness: 0.65, metalness: 0.4 });
  const accent = new THREE.MeshStandardMaterial({ color: 0x0e0e13, roughness: 0.5, metalness: 0.6 });

  // ---- chassi / corpo ----
  const main = new RoundedBoxGeometry(1.94, 0.56, 4.55, 4, 0.09);
  const mainMesh = mesh(main, paintMat, body);
  mainMesh.position.set(0, 0.63, 0);

  const mid = new RoundedBoxGeometry(1.88, 0.3, 3.9, 3, 0.07);
  const midMesh = mesh(mid, paintMat, body);
  midMesh.position.set(0, 0.9, 0.02);

  // capô dianteiro e tampa traseira
  const hood = new RoundedBoxGeometry(1.82, 0.16, 2.05, 3, 0.055);
  const hoodMesh = mesh(hood, paintMat, body);
  hoodMesh.position.set(0, 0.99, 1.28);
  hoodMesh.rotation.x = -0.012;

  const deck = new RoundedBoxGeometry(1.8, 0.14, 1.5, 3, 0.05);
  const deckMesh = mesh(deck, paintMat, body);
  deckMesh.position.set(0, 0.985, -1.62);

  // para-choques
  const fBumper = new RoundedBoxGeometry(1.92, 0.26, 0.22, 3, 0.06);
  const fBump = mesh(fBumper, paintMat, body);
  fBump.position.set(0, 0.6, 2.28);
  const rBumper = new RoundedBoxGeometry(1.9, 0.28, 0.2, 3, 0.06);
  const rBump = mesh(rBumper, paintMat, body);
  rBump.position.set(0, 0.62, -2.26);

  // saias laterais
  for (const sx of [-1, 1]) {
    const skirt = mesh(new RoundedBoxGeometry(0.13, 0.16, 3.1, 2, 0.03), accent, body);
    skirt.position.set(sx * 0.92, 0.38, -0.05);
  }

  // grade / boca
  const grille = mesh(new RoundedBoxGeometry(1.34, 0.2, 0.08, 2, 0.03), paintDark, body, false);
  grille.position.set(0, 0.72, 2.36);
  const grilleIn = mesh(new RoundedBoxGeometry(1.12, 0.13, 0.02, 2, 0.02), new THREE.MeshStandardMaterial({ color: 0x050508, roughness: 0.9 }), body, false);
  grilleIn.position.set(0, 0.72, 2.4);

  // faróis
  for (const sx of [-1, 1]) {
    const hl = mesh(new RoundedBoxGeometry(0.44, 0.17, 0.08, 3, 0.035), mats.headlight, body, false);
    hl.position.set(sx * 0.6, 0.88, 2.34);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture(), color: 0xffe9b0, transparent: true, opacity: 0.6,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    glow.scale.set(1.1, 1.1, 1);
    glow.position.set(sx * 0.6, 0.88, 2.43);
    body.add(glow);

    // lanternas
    const tl = mesh(new RoundedBoxGeometry(0.38, 0.14, 0.06, 2, 0.03), mats.taillight, body, false);
    tl.position.set(sx * 0.66, 0.9, -2.31);
  }
  // barra de led traseira
  const ledBar = mesh(new RoundedBoxGeometry(1.45, 0.045, 0.04, 2, 0.015), mats.taillight, body, false);
  ledBar.position.set(0, 0.83, -2.33);

  // grade traseira
  const rearPanel = mesh(new RoundedBoxGeometry(1.5, 0.24, 0.04, 2, 0.02), paintDark, body, false);
  rearPanel.position.set(0, 0.64, -2.34);

  // scoop no capô
  const scoop = mesh(new RoundedBoxGeometry(0.62, 0.16, 0.78, 3, 0.05), paintMat, body);
  scoop.position.set(0, 1.08, 1.3);

  // aerofólio
  const wing = mesh(new RoundedBoxGeometry(1.62, 0.055, 0.34, 2, 0.02), accent, body);
  wing.position.set(0, 1.13, -2.0);
  for (const sx of [-1, 1]) {
    const strut = mesh(new THREE.BoxGeometry(0.05, 0.18, 0.14), accent, body);
    strut.position.set(sx * 0.56, 1.03, -2.0);
  }

  // retrovisores
  for (const sx of [-1, 1]) {
    const m = mesh(new RoundedBoxGeometry(0.22, 0.1, 0.13, 2, 0.03), paintMat, body);
    m.position.set(sx * 1.01, 1.03, 0.5);
    const arm = mesh(new THREE.BoxGeometry(0.12, 0.03, 0.04), accent, body);
    arm.position.set(sx * 0.94, 0.98, 0.5);
  }

  // escapamentos
  const exhaustTips = [];
  for (const sx of [-1, 1]) {
    const tip = mesh(new THREE.CylinderGeometry(0.056, 0.062, 0.22, 14), mats.chrome, body, false);
    tip.rotation.x = Math.PI / 2;
    tip.position.set(sx * 0.58, 0.38, -2.36);
    exhaustTips.push(tip);
    const inner = mesh(new THREE.CylinderGeometry(0.042, 0.042, 0.06, 12), new THREE.MeshBasicMaterial({ color: 0x050505 }), body, false);
    inner.rotation.x = Math.PI / 2;
    inner.position.set(sx * 0.58, 0.38, -2.45);
  }

  // ---- cabine ----
  const roof = mesh(new RoundedBoxGeometry(1.5, 0.07, 1.44, 3, 0.03), paintMat, body);
  roof.position.set(0, 1.455, -0.28);

  const glassMat = mats.glass;
  const windshield = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 0.62), glassMat);
  windshield.position.set(0, 1.22, 0.58);
  windshield.rotation.x = -0.46;
  body.add(windshield);
  const rearGlass = new THREE.Mesh(new THREE.PlaneGeometry(1.48, 0.55), glassMat);
  rearGlass.position.set(0, 1.22, -1.02);
  rearGlass.rotation.x = 0.5;
  body.add(rearGlass);
  for (const sx of [-1, 1]) {
    const sideGlass = new THREE.Mesh(new THREE.PlaneGeometry(1.34, 0.42), glassMat);
    sideGlass.position.set(sx * 0.755, 1.21, -0.24);
    sideGlass.rotation.y = sx * Math.PI / 2;
    body.add(sideGlass);
    // colunas A e B
    for (const zz of [0.58, -1.02]) {
      const pillar = mesh(new THREE.BoxGeometry(0.055, 0.54, 0.08), accent, body);
      pillar.position.set(sx * 0.75, 1.22, zz);
      pillar.rotation.x = zz > 0 ? -0.42 : 0.42;
    }
  }

  // faixa no teto
  const roofStripe = mesh(new RoundedBoxGeometry(0.5, 0.012, 1.4, 2, 0.006), new THREE.MeshStandardMaterial({ color: 0xf2efe4, roughness: 0.45, metalness: 0.2 }), body, false);
  roofStripe.position.set(0, 1.493, -0.28);

  // sombra de contato
  const shadow = new THREE.Mesh(
    new THREE.PlaneGeometry(2.7, 5.2),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.55, depthWrite: false })
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.012;
  shadow.material.alphaMap = glowTexture();
  shadow.material.opacity = 0.55;
  root.add(shadow);

  // ---- interior ----
  let steeringWheel = null;
  const needles = { tach: null, speed: null };
  if (interior) {
    const dash = mesh(new RoundedBoxGeometry(1.58, 0.22, 0.46, 3, 0.04), mats.interior, body);
    dash.position.set(0, 1.02, 0.63);
    const dashTop = mesh(new RoundedBoxGeometry(1.58, 0.06, 0.5, 2, 0.02), new THREE.MeshStandardMaterial({ color: 0x1c1b21, roughness: 0.75 }), body);
    dashTop.position.set(0, 1.15, 0.6);
    dashTop.rotation.x = -0.12;

    // painel de instrumentos
    const cluster = new THREE.Group();
    cluster.position.set(-0.37, 1.06, 0.47);
    cluster.rotation.x = -0.28;
    body.add(cluster);
    const clusterPanel = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.19, 0.04), new THREE.MeshStandardMaterial({ color: 0x08080b, roughness: 0.5 }));
    cluster.add(clusterPanel);
    for (const [i, x] of [-0.155, 0.155].entries()) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.077, 0.007, 6, 24), mats.chrome);
      ring.position.set(x, 0, -0.028);
      cluster.add(ring);
      const dial = new THREE.Mesh(new THREE.CircleGeometry(0.071, 24), new THREE.MeshBasicMaterial({ color: 0x11131c }));
      dial.position.set(x, 0, -0.03);
      cluster.add(dial);
      const needle = new THREE.Mesh(new THREE.BoxGeometry(0.008, 0.062, 0.004), new THREE.MeshBasicMaterial({ color: i === 0 ? 0xff3b2f : 0xffd319 }));
      needle.geometry.translate(0, 0.028, 0);
      needle.position.set(x, 0, -0.036);
      needle.rotation.z = 2.2;
      cluster.add(needle);
      if (i === 0) needles.tach = needle;
      else needles.speed = needle;
    }
    // luzes do painel
    const ledMat = new THREE.MeshBasicMaterial({ color: 0x37e6ff });
    for (let i = 0; i < 3; i++) {
      const led = new THREE.Mesh(new THREE.CircleGeometry(0.008, 8), ledMat);
      led.position.set(-0.1 + i * 0.05, -0.075, -0.035);
      cluster.add(led);
    }

    // volante
    steeringWheel = new THREE.Group();
    steeringWheel.position.set(-0.37, 1.0, 0.34);
    steeringWheel.rotation.x = -0.5;
    body.add(steeringWheel);
    const rim = new THREE.Mesh(new THREE.TorusGeometry(0.155, 0.021, 10, 32), new THREE.MeshStandardMaterial({ color: 0x0d0d10, roughness: 0.55, metalness: 0.2 }));
    steeringWheel.add(rim);
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * Math.PI * 2 + Math.PI / 6;
      const spoke = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.13, 0.014), mats.chrome);
      spoke.position.set(Math.cos(a) * 0.07, Math.sin(a) * 0.07, 0);
      spoke.rotation.z = a + Math.PI / 2;
      steeringWheel.add(spoke);
    }
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 0.025, 14), mats.rimDark);
    hub.rotation.x = Math.PI / 2;
    steeringWheel.add(hub);
    // marcador amarelo no topo do volante
    const marker = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.02, 0.012), new THREE.MeshBasicMaterial({ color: 0xffd319 }));
    marker.position.set(0, 0.155, 0);
    steeringWheel.add(marker);

    // alavanca
    const lever = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.018, 0.24, 8), mats.chrome);
    lever.position.set(0.03, 0.9, 0.28);
    lever.rotation.x = 0.25;
    body.add(lever);
    const knob = new THREE.Mesh(new THREE.SphereGeometry(0.042, 12, 10), new THREE.MeshStandardMaterial({ color: 0xff5a12, roughness: 0.35 }));
    knob.position.set(0.03, 1.02, 0.31);
    body.add(knob);

    // bancos
    for (const [sx, mat] of [[-0.37, mats.seatRed], [0.4, mats.seat]]) {
      const base = mesh(new RoundedBoxGeometry(0.52, 0.16, 0.55, 2, 0.05), mat, body);
      base.position.set(sx, 0.72, -0.42);
      const back = mesh(new RoundedBoxGeometry(0.52, 0.76, 0.17, 2, 0.07), mat, body);
      back.position.set(sx, 1.04, -0.74);
      back.rotation.x = -0.12;
      const head = mesh(new RoundedBoxGeometry(0.3, 0.18, 0.13, 2, 0.05), mat, body);
      head.position.set(sx, 1.4, -0.78);
      head.rotation.x = -0.12;
    }

    // painéis de porta
    for (const sx of [-1, 1]) {
      const door = mesh(new RoundedBoxGeometry(0.08, 0.44, 1.5, 2, 0.03), mats.interior, body);
      door.position.set(sx * 0.83, 0.79, -0.25);
    }

    // retrovisor interno
    const mirror = mesh(new RoundedBoxGeometry(0.26, 0.07, 0.045, 2, 0.02), mats.interior, body, false);
    mirror.position.set(0, 1.4, 0.32);
    mirror.rotation.x = -0.2;

    // arco de segurança estilizado
    const cage = new THREE.Mesh(new THREE.TorusGeometry(0.72, 0.026, 6, 20, Math.PI), mats.chrome);
    cage.position.set(0, 1.04, -0.86);
    cage.rotation.y = Math.PI / 2;
    body.add(cage);
  }

  // ---- rodas ----
  const wheels = [
    wheel(-0.88, 1.43, -1, true),
    wheel(0.88, 1.43, 1, true),
    wheel(-0.91, -1.45, -1, false),
    wheel(0.91, -1.45, 1, false),
  ];
  for (const w of wheels) root.add(w.group);

  // ---- luzes de freio ----
  const tailMats = [];
  body.traverse((o) => {
    if (o.isMesh && o.material === mats.taillight) tailMats.push(o.material);
  });

  function setPaint(hex) {
    paintMat.color.set(hex);
  }

  return {
    root,
    body,
    wheels,
    paintMat,
    steeringWheel,
    needles,
    exhaustTips,
    setPaint,
  };
}

import * as THREE from "three";
import {
  asphaltTexture, checkerTexture, bannerTexture, signTexture,
  windowsTexture, glowTexture, lightPoolTexture, crowdTexture,
} from "./textures.js";

const LANE = 4.2;
const FINISH = 402.336;

export function buildTrack() {
  const group = new THREE.Group();
  const animated = [];

  // ---- chão ----
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(900, 1200),
    new THREE.MeshStandardMaterial({ color: 0x090a0f, roughness: 1, metalness: 0 })
  );
  ground.rotation.x = -Math.PI / 2;
  ground.position.set(0, -0.04, 220);
  ground.receiveShadow = true;
  group.add(ground);

  // faixa de asfalto
  const asphalt = asphaltTexture();
  const strip = new THREE.Mesh(
    new THREE.PlaneGeometry(20, 620),
    new THREE.MeshStandardMaterial({ map: asphalt, color: 0xa7a7b0, roughness: 0.92, metalness: 0.02 })
  );
  strip.rotation.x = -Math.PI / 2;
  strip.position.set(0, 0, 240);
  strip.receiveShadow = true;
  group.add(strip);

  // acostamento / concreto
  for (const sx of [-1, 1]) {
    const shoulder = new THREE.Mesh(
      new THREE.PlaneGeometry(6, 620),
      new THREE.MeshStandardMaterial({ color: 0x15151b, roughness: 0.95 })
    );
    shoulder.rotation.x = -Math.PI / 2;
    shoulder.position.set(sx * 13, -0.01, 240);
    group.add(shoulder);
  }

  // área de fuga
  const sand = new THREE.Mesh(
    new THREE.PlaneGeometry(30, 120),
    new THREE.MeshStandardMaterial({ color: 0x3a3026, roughness: 1 })
  );
  sand.rotation.x = -Math.PI / 2;
  sand.position.set(0, -0.005, 530);
  group.add(sand);

  // ---- linhas ----
  const lineMat = new THREE.MeshStandardMaterial({ color: 0xdad7cc, roughness: 0.7, emissive: 0x2a2a26, emissiveIntensity: 0.4 });
  const yellowMat = new THREE.MeshStandardMaterial({ color: 0xd6b227, roughness: 0.75, emissive: 0x3a2c00, emissiveIntensity: 0.5 });

  for (const sx of [-1, 1]) {
    const edge = new THREE.Mesh(new THREE.PlaneGeometry(0.16, 600), lineMat);
    edge.rotation.x = -Math.PI / 2;
    edge.position.set(sx * 9.7, 0.012, 240);
    group.add(edge);
  }
  for (const x of [-0.16, 0.16]) {
    const center = new THREE.Mesh(new THREE.PlaneGeometry(0.1, 600), yellowMat);
    center.rotation.x = -Math.PI / 2;
    center.position.set(x, 0.013, 240);
    group.add(center);
  }

  // linha de largada e chegada
  const checker = checkerTexture();
  for (const [z, w] of [[0, 20], [FINISH, 20]]) {
    const line = new THREE.Mesh(
      new THREE.PlaneGeometry(w, 1.1),
      new THREE.MeshBasicMaterial({ map: checker })
    );
    line.rotation.x = -Math.PI / 2;
    line.position.set(0, 0.02, z);
    group.add(line);
  }

  // posições de largada
  for (const lane of [-1, 1]) {
    const box = new THREE.Mesh(
      new THREE.PlaneGeometry(1.2, 6),
      new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.07 })
    );
    box.rotation.x = -Math.PI / 2;
    box.position.set(lane * LANE, 0.015, -3.5);
    group.add(box);
  }

  // ---- muros e placas ----
  const railMat = new THREE.MeshStandardMaterial({ color: 0x23242c, roughness: 0.55, metalness: 0.6 });
  for (const sx of [-1, 1]) {
    const rail = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.85, 560), railMat);
    rail.position.set(sx * 11.8, 0.42, 220);
    rail.castShadow = false;
    rail.receiveShadow = true;
    group.add(rail);
    const railTop = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.09, 560), new THREE.MeshStandardMaterial({ color: 0x44454f, roughness: 0.4, metalness: 0.7 }));
    railTop.position.set(sx * 11.8, 0.87, 220);
    group.add(railTop);
    // postes do guard-rail
    for (let z = -20; z < 500; z += 12) {
      const post = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.85, 0.1), railMat);
      post.position.set(sx * 11.95, 0.42, z);
      group.add(post);
    }
  }

  // banners nos muros
  const bannerTexts = [
    ["DRAG BRASIL", "#0b0b12", "#ffd319", "#ff5a12"],
    ["NITRO", "#101018", "#37e6ff", "#1b63ff"],
    ["TURBO", "#120c08", "#ff8a3d", "#ff5a12"],
    ["GASOLINA", "#0b0f0c", "#2dff86", "#1f9c55"],
    ["PNEU FUDIDO", "#0e0a12", "#e8e6df", "#8c2bff"],
    ["402 METROS", "#0f0b0b", "#ff2e4d", "#7d0719"],
  ];
  for (let i = 0; i < 18; i++) {
    const z = -16 + i * 26;
    if (z > 410) break;
    const tex = bannerTexture(...bannerTexts[i % bannerTexts.length]);
    for (const sx of [-1, 1]) {
      if ((i + (sx > 0 ? 1 : 0)) % 3 === 0) continue;
      const sign = new THREE.Mesh(
        new THREE.PlaneGeometry(9, 0.8),
        new THREE.MeshBasicMaterial({ map: tex, transparent: true })
      );
      sign.position.set(sx * 11.7, 0.48, z);
      sign.rotation.y = sx > 0 ? -Math.PI / 2 : Math.PI / 2;
      group.add(sign);
    }
  }

  // ---- postes de iluminação ----
  const poolTex = lightPoolTexture();
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x1d1e25, roughness: 0.6, metalness: 0.6 });
  const bulbMat = new THREE.MeshStandardMaterial({ color: 0xfff4d0, emissive: 0xfff1c8, emissiveIntensity: 4.5, roughness: 0.3 });
  const glowTex = glowTexture();
  for (let z = -30; z < 480; z += 48) {
    for (const sx of [-1, 1]) {
      const x = sx * 15.5;
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.2, 9, 8), poleMat);
      pole.position.set(x, 4.5, z);
      group.add(pole);
      const arm = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.12, 0.12), poleMat);
      arm.position.set(x - sx * 1.1, 8.9, z);
      group.add(arm);
      const lamp = new THREE.Mesh(new THREE.BoxGeometry(1.1, 0.12, 0.5), bulbMat);
      lamp.position.set(x - sx * 2.1, 8.82, z);
      group.add(lamp);
      const halo = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTex, color: 0xffe6b0, transparent: true, opacity: 0.55,
        blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      halo.scale.set(7, 5, 1);
      halo.position.set(x - sx * 2.1, 8.6, z);
      group.add(halo);

      const pool = new THREE.Mesh(
        new THREE.PlaneGeometry(26, 26),
        new THREE.MeshBasicMaterial({ map: poolTex, transparent: true, opacity: 0.4, blending: THREE.AdditiveBlending, depthWrite: false })
      );
      pool.rotation.x = -Math.PI / 2;
      pool.position.set(x - sx * 3, 0.03, z);
      group.add(pool);
    }
  }

  // luzes de verdade perto do jogador (baratas)
  const lightZ = [10, 150, 300, 405];
  for (const z of lightZ) {
    const pl = new THREE.PointLight(0xffe3b0, 90, 70, 2);
    pl.position.set(0, 9, z);
    group.add(pl);
  }

  // ---- arquibancada ----
  const standMat = new THREE.MeshStandardMaterial({ color: 0x121219, roughness: 0.9 });
  const crowd = crowdTexture();
  const crowdMat = new THREE.MeshBasicMaterial({ map: crowd, transparent: true });
  for (const sx of [-1, 1]) {
    const stand = new THREE.Group();
    for (let i = 0; i < 5; i++) {
      const step = new THREE.Mesh(new THREE.BoxGeometry(6, 1.1, 2.6), standMat);
      step.position.set(sx * (24 + i * 1.9), 0.55 + i * 1.1, -8);
      step.receiveShadow = true;
      stand.add(step);
      const people = new THREE.Mesh(new THREE.PlaneGeometry(26, 1.0), crowdMat);
      people.rotation.y = sx > 0 ? -Math.PI / 2 : Math.PI / 2;
      people.position.set(sx * (23 + i * 1.9), 1.0 + i * 1.1, -8);
      stand.add(people);
    }
    const roof = new THREE.Mesh(new THREE.BoxGeometry(10, 0.16, 28), standMat);
    roof.position.set(sx * 28, 8.6, -8);
    stand.add(roof);
