import * as THREE from "three";
import { smokeTexture, glowTexture } from "./textures.js";

function makePoints(count, texture, { additive = false, color = 0xffffff } = {}) {
  const geo = new THREE.BufferGeometry();
  const positions = new Float32Array(count * 3);
  const sizes = new Float32Array(count);
  const alphas = new Float32Array(count);
  for (let i = 0; i < count; i++) positions[i * 3 + 1] = -1000;
  geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geo.setAttribute("aSize", new THREE.BufferAttribute(sizes, 1));
  geo.setAttribute("aAlpha", new THREE.BufferAttribute(alphas, 1));

  const mat = new THREE.ShaderMaterial({
    uniforms: {
      uTex: { value: texture },
      uColor: { value: new THREE.Color(color) },
      uScale: { value: 1 },
    },
    vertexShader: `
      attribute float aSize;
      attribute float aAlpha;
      varying float vAlpha;
      uniform float uScale;
      void main() {
        vAlpha = aAlpha;
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = aSize * uScale * (280.0 / max(-mv.z, 0.1));
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: `
      uniform sampler2D uTex;
      uniform vec3 uColor;
      varying float vAlpha;
      void main() {
        vec4 t = texture2D(uTex, gl_PointCoord);
        gl_FragColor = vec4(uColor, t.a * vAlpha);
      }
    `,
    transparent: true,
    depthWrite: false,
    blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
  });
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  return { geo, mat, points, positions, sizes, alphas, count };
}

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.smoke = makePoints(320, smokeTexture(), { color: 0xd7d9e2 });
    this.smoke.mat.uniforms.uScale.value = 1;
    scene.add(this.smoke.points);

    this.fire = makePoints(120, glowTexture(), { additive: true, color: 0xff9a3a });
    scene.add(this.fire.points);

    this.smokeParts = Array.from({ length: this.smoke.count }, () => ({ alive: false, x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, life: 0, max: 1, size: 1 }));
    this.fireParts = Array.from({ length: this.fire.count }, () => ({ alive: false, x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, life: 0, max: 1, size: 1 }));
    this.si = 0;
    this.fi = 0;
    this._tmp = new THREE.Vector3();
  }

  emitSmoke(pos, intensity = 1, dir = null) {
    for (let n = 0; n < Math.max(1, Math.round(intensity * 2)); n++) {
      const p = this.smokeParts[this.si];
      this.si = (this.si + 1) % this.smokeParts.length;
      p.alive = true;
      p.x = pos.x + (Math.random() - 0.5) * 0.3;
      p.y = pos.y + Math.random() * 0.12;
      p.z = pos.z + (Math.random() - 0.5) * 0.3;
      const spread = 0.5 + intensity * 1.2;
      p.vx = (Math.random() - 0.5) * spread + (dir ? dir.x * intensity * 0.6 : 0);
      p.vy = 0.3 + Math.random() * 0.7;
      p.vz = (Math.random() - 0.5) * spread + (dir ? dir.z * intensity * 0.6 : 0);
      p.max = 1.1 + Math.random() * 1.5;
      p.life = p.max;
      p.size = 26 + Math.random() * 26 + intensity * 16;
    }
  }

  emitBackfire(pos, dir) {
    for (let n = 0; n < 5; n++) {
      const p = this.fireParts[this.fi];
      this.fi = (this.fi + 1) % this.fireParts.length;
      p.alive = true;
      p.x = pos.x;
      p.y = pos.y;
      p.z = pos.z;
      p.vx = (Math.random() - 0.5) * 1.4 + dir.x * 3;
      p.vy = (Math.random() - 0.5) * 0.8 + 0.3;
      p.vz = (Math.random() - 0.5) * 1.4 + dir.z * 3;
      p.max = 0.16 + Math.random() * 0.16;
      p.life = p.max;
      p.size = 14 + Math.random() * 16;
    }
  }

  update(dt) {
    const dtc = Math.min(dt, 0.05);
    const s = this.smoke;
    for (let i = 0; i < s.count; i++) {
      const p = this.smokeParts[i];
      if (!p.alive) {
        s.alphas[i] = 0;
        continue;
      }
      p.life -= dtc;
      if (p.life <= 0) {
        p.alive = false;
        s.alphas[i] = 0;
        continue;
      }
      p.x += p.vx * dtc;
      p.y += p.vy * dtc;
      p.z += p.vz * dtc;
      p.vy += 0.55 * dtc;
      p.vx *= 1 - dtc * 1.6;
      p.vz *= 1 - dtc * 1.6;
      const t = p.life / p.max;
      s.positions[i * 3] = p.x;
      s.positions[i * 3 + 1] = p.y;
      s.positions[i * 3 + 2] = p.z;
      s.sizes[i] = p.size * (1.4 - t * 0.5);
      s.alphas[i] = Math.min(1, t * 1.8) * 0.30;
    }
    s.geo.attributes.position.needsUpdate = true;
    s.geo.attributes.aSize.needsUpdate = true;
    s.geo.attributes.aAlpha.needsUpdate = true;

    const f = this.fire;
    for (let i = 0; i < f.count; i++) {
      const p = this.fireParts[i];
      if (!p.alive) {
        f.alphas[i] = 0;
        continue;
      }
      p.life -= dtc;
      if (p.life <= 0) {
        p.alive = false;
        f.alphas[i] = 0;
        continue;
      }
      p.x += p.vx * dtc;
      p.y += p.vy * dtc;
      p.z += p.vz * dtc;
      p.vx *= 1 - dtc * 4;
      p.vy *= 1 - dtc * 3;
      p.vz *= 1 - dtc * 4;
      const t = p.life / p.max;
      f.positions[i * 3] = p.x;
      f.positions[i * 3 + 1] = p.y;
      f.positions[i * 3 + 2] = p.z;
      f.sizes[i] = p.size * (0.6 + t * 0.9);
      f.alphas[i] = t;
    }
    f.geo.attributes.position.needsUpdate = true;
    f.geo.attributes.aSize.needsUpdate = true;
    f.geo.attributes.aAlpha.needsUpdate = true;
  }

  clear() {
    for (const p of this.smokeParts) p.alive = false;
    for (const p of this.fireParts) p.alive = false;
    for (let i = 0; i < this.smoke.count; i++) this.smoke.alphas[i] = 0;
    for (let i = 0; i < this.fire.count; i++) this.fire.alphas[i] = 0;
    this.smoke.geo.attributes.aAlpha.needsUpdate = true;
    this.fire.geo.attributes.aAlpha.needsUpdate = true;
  }
}

// Motor sonoro 100% sintetizado (WebAudio) — nenhum arquivo de áudio necessário.

function noiseBuffer(ctx, seconds = 2) {
  const len = Math.floor(ctx.sampleRate * seconds);
  const buf = ctx.createBuffer(1, len, ctx.sampleRate);
  const d = buf.getChannelData(0);
  let last = 0;
  for (let i = 0; i < len; i++) {
    const white = Math.random() * 2 - 1;
    last = (last + 0.02 * white) / 1.02;
    d[i] = last * 3.2;
  }
  return buf;
}

export class GameAudio {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.ready = false;
    this.lastPop = 0;
  }

  async init() {
    if (this.ready) {
      if (this.ctx.state === "suspended") await this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    this.ctx = ctx;
    await ctx.resume();

    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.85;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 20;
    comp.ratio.value = 5;
    comp.attack.value = 0.005;
    comp.release.value = 0.18;
    this.master.connect(comp);
    comp.connect(ctx.destination);

    this.noiseBuf = noiseBuffer(ctx, 2.5);

    // ---- motor ----
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0.0;
    this.engineFilter = ctx.createBiquadFilter();
    this.engineFilter.type = "lowpass";
    this.engineFilter.frequency.value = 600;
    this.engineFilter.Q.value = 1.4;
    this.engineGain.connect(this.engineFilter);
    this.engineFilter.connect(this.master);

    const mk = (type, gain, oct = 1) => {
      const o = ctx.createOscillator();
      o.type = type;
      o.frequency.value = 40 * oct;
      const g = ctx.createGain();
      g.gain.value = gain;
      o.connect(g);
      g.connect(this.engineGain);
      o.start();
      return { o, g };
    };
    this.oscs = [mk("sawtooth", 0.5), mk("sawtooth", 0.35, 1.01), mk("square", 0.14, 2), mk("sine", 0.5, 0.5)];

    // aspereza do escape
    this.exhaustNoise = ctx.createBufferSource();
    this.exhaustNoise.buffer = this.noiseBuf;
    this.exhaustNoise.loop = true;
    this.exhaustFilter = ctx.createBiquadFilter();
    this.exhaustFilter.type = "bandpass";
    this.exhaustFilter.frequency.value = 260;
    this.exhaustFilter.Q.value = 0.9;
    this.exhaustGain = ctx.createGain();
    this.exhaustGain.gain.value = 0.0;
    this.exhaustNoise.connect(this.exhaustFilter);
    this.exhaustFilter.connect(this.exhaustGain);
    this.exhaustGain.connect(this.master);
    this.exhaustNoise.start();

    // ---- turbo ----
    this.turboOsc = ctx.createOscillator();
    this.turboOsc.type = "sine";
    this.turboOsc.frequency.value = 1800;
    this.turboGain = ctx.createGain();
    this.turboGain.gain.value = 0;
    this.turboOsc.connect(this.turboGain);
    this.turboGain.connect(this.master);
    this.turboOsc.start();

    // ---- pneus ----
    this.tireNoise = ctx.createBufferSource();
    this.tireNoise.buffer = this.noiseBuf;
    this.tireNoise.loop = true;
    this.tireFilter = ctx.createBiquadFilter();
    this.tireFilter.type = "bandpass";
    this.tireFilter.frequency.value = 2100;
    this.tireFilter.Q.value = 9;
    this.tireGain = ctx.createGain();
    this.tireGain.gain.value = 0;
    this.tireNoise.connect(this.tireFilter);
    this.tireFilter.connect(this.tireGain);
    this.tireGain.connect(this.master);
    this.tireNoise.start();

    // ---- vento ----
    this.windNoise = ctx.createBufferSource();
    this.windNoise.buffer = this.noiseBuf;
    this.windNoise.loop = true;
    this.windFilter = ctx.createBiquadFilter();
    this.windFilter.type = "lowpass";
    this.windFilter.frequency.value = 500;
    this.windGain = ctx.createGain();
    this.windGain.gain.value = 0;
    this.windNoise.connect(this.windFilter);
    this.windFilter.connect(this.windGain);
    this.windGain.connect(this.master);
    this.windNoise.start();

    // ---- torcida ----
    this.crowdNoise = ctx.createBufferSource();
    this.crowdNoise.buffer = this.noiseBuf;
    this.crowdNoise.loop = true;
    this.crowdFilter = ctx.createBiquadFilter();
    this.crowdFilter.type = "bandpass";
    this.crowdFilter.frequency.value = 650;
    this.crowdFilter.Q.value = 0.6;
    this.crowdGain = ctx.createGain();
    this.crowdGain.gain.value = 0.012;
    this.crowdNoise.connect(this.crowdFilter);
    this.crowdFilter.connect(this.crowdGain);
    this.crowdGain.connect(this.master);
    this.crowdNoise.start();

    this.ready = true;
  }

  setMuted(m) {
    this.muted = m;
    if (!this.ctx) return;
    this.master.gain.setTargetAtTime(m ? 0 : 0.85, this.ctx.currentTime, 0.03);
  }

  update(s) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const rpm = s.rpm || 850;
    const norm = Math.max(0, Math.min(1.15, s.rpmNorm || 0));
    const f = Math.max(22, (rpm / 60) * 2.15);
    for (const { o, g } of this.oscs) {
      const oct = g === this.oscs[0].g ? 1 : g === this.oscs[1].g ? 1.01 : g === this.oscs[2].g ? 2 : 0.5;
      o.frequency.setTargetAtTime(f * oct, t, 0.02);
    }
    const running = s.racing ? 1 : 0.45;
    const load = s.racing ? (0.35 + 0.65 * (s.throttle || 0)) : 0.2;
    const eg = running * load * (0.055 + norm * 0.075);
    this.engineGain.gain.setTargetAtTime(eg, t, 0.045);
    this.engineFilter.frequency.setTargetAtTime(260 + norm * 1200 + (s.throttle || 0) * 700, t, 0.05);
    this.exhaustGain.gain.setTargetAtTime((s.racing ? 0.035 : 0.01) * (0.35 + (s.throttle || 0)) * (0.5 + norm * 0.8), t, 0.06);

    const turbo = s.racing ? Math.max(0, norm - 0.4) * (0.6 + (s.throttle || 0)) : 0;
    this.turboOsc.frequency.setTargetAtTime(1500 + norm * 2700, t, 0.06);
    this.turboGain.gain.setTargetAtTime(turbo * 0.02, t, 0.08);

    const slip = Math.min(1, s.slip || 0);
    this.tireGain.gain.setTargetAtTime(slip * 0.15, t, 0.05);
    this.tireFilter.frequency.setTargetAtTime(1650 + slip * 900, t, 0.1);

    this.windFilter.frequency.setTargetAtTime(380 + Math.min(1, (s.speed || 0) / 80) * 900, t, 0.2);
    this.windGain.gain.setTargetAtTime(Math.min(0.09, (s.speed || 0) * 0.0014), t, 0.15);
  }

  beep(freq = 700, dur = 0.09, vol = 0.16, type = "square") {
    if (!this.ready) return;
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.value = freq;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(vol, ctx.currentTime + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + dur);
    o.connect(g);
    g.connect(this.master);
    o.start();
    o.stop(ctx.currentTime + dur + 0.02);
  }

  pop(strength = 1) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    if (t - this.lastPop < 0.035) return;
    this.lastPop = t;

    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    src.playbackRate.value = 0.7 + Math.random() * 0.6;
    const f = ctx.createBiquadFilter();
    f.type = "lowpass";
    f.frequency.setValueAtTime(1200, t);
    f.frequency.exponentialRampToValueAtTime(260, t + 0.14);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.34 * strength, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.17);
    src.connect(f);
    f.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + 0.2);

    const thump = ctx.createOscillator();
    thump.type = "sine";
    thump.frequency.setValueAtTime(110, t);
    thump.frequency.exponentialRampToValueAtTime(45, t + 0.12);
    const tg = ctx.createGain();
    tg.gain.setValueAtTime(0.22 * strength, t);
    tg.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
    thump.connect(tg);
    tg.connect(this.master);
    thump.start(t);
    thump.stop(t + 0.16);
  }

  whoosh() {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    src.playbackRate.value = 1.4;
    const f = ctx.createBiquadFilter();
    f.type = "bandpass";
    f.frequency.setValueAtTime(2400, t);
    f.frequency.exponentialRampToValueAtTime(700, t + 0.3);
    f.Q.value = 1.5;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.09, t + 0.03);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.32);
    src.connect(f);
    f.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + 0.34);
  }

  foul() {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const o = ctx.createOscillator();
    o.type = "sawtooth";
    o.frequency.value = 120;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.12, t);
    g.gain.setValueAtTime(0.12, t + 0.3);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
    o.connect(g);
    g.connect(this.master);
    o.start(t);
    o.stop(t + 0.52);
  }

  win() {
    if (!this.ready) return;
    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((f, i) => {
      const ctx = this.ctx;
      const t = ctx.currentTime + i * 0.09;
      const o = ctx.createOscillator();
      o.type = "triangle";
      o.frequency.value = f;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.16, t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.45);
      o.connect(g);
      g.connect(this.master);
      o.start(t);
      o.stop(t + 0.5);
    });
    // torcida
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    src.loop = true;
    src.playbackRate.value = 1.1;
    const f = ctx.createBiquadFilter();
    f.type = "bandpass";
    f.frequency.value = 900;
    f.Q.value = 0.7;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.07, t + 0.2);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.9);
    src.connect(f);
    f.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + 2);
  }

  lose() {
    if (!this.ready) return;
    const ctx = this.ctx;
    [220, 174.6].forEach((fr, i) => {
      const t = ctx.currentTime + i * 0.18;
      const o = ctx.createOscillator();
      o.type = "sawtooth";
      o.frequency.value = fr;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.08, t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.5);
      o.connect(g);
      g.connect(this.master);
      o.start(t);
      o.stop(t + 0.52);
    });
  }

  ui() {
    this.beep(950, 0.045, 0.05, "triangle");
  }
}

const KEY = "dragbrasil.save.v1";

const defaultUpgrades = () => ({ engine: 0, tires: 0, weight: 0, gearbox: 0 });

export function defaultSave() {
  return {
    money: 750,
    ownedCars: ["falcao"],
    selected: "falcao",
    paints: { falcao: "laranja" },
    upgrades: { falcao: defaultUpgrades() },
    wins: 0,
    losses: 0,
    races: 0,
    bestET: null,
    bestTrap: null,
    sound: true,
    careerWins: 0,
    seenHelp: false,
  };
}

export function loadSave() {
  const base = defaultSave();
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return base;
    const data = JSON.parse(raw);
    const merged = { ...base, ...data };
    merged.ownedCars = Array.isArray(data.ownedCars) && data.ownedCars.length ? data.ownedCars : base.ownedCars;
    if (!merged.ownedCars.includes(merged.selected)) merged.selected = merged.ownedCars[0];
    merged.upgrades = { ...base.upgrades, ...(data.upgrades || {}) };
    for (const id of Object.keys(merged.upgrades)) {
      merged.upgrades[id] = { ...defaultUpgrades(), ...merged.upgrades[id] };
    }
    merged.paints = { ...base.paints, ...(data.paints || {}) };
    return merged;
  } catch {
    return base;
  }
}

export function persist(save) {
  try {
    localStorage.setItem(KEY, JSON.stringify(save));
  } catch {
    /* storage cheio ou bloqueado — o jogo continua */
  }
}

export function money(n) {
  return "R$ " + Math.round(n).toLocaleString("pt-BR");
}

export function fmtTime(t) {
  if (t == null || !isFinite(t)) return "—";
  return t.toFixed(3) + "s";
}

import { CARS, UPGRADES, upgradeCost, estimatePower, buildSpec, PAINTS, carById } from "./data.js";
import { money, fmtTime } from "./save.js";

const $ = (id) => document.getElementById(id);

export class UI {
  constructor(game) {
    this.game = game;
    this.el = {
      boot: $("boot"),
      menu: $("menu"),
      garage: $("garage"),
      help: $("help"),
      hud: $("hud"),
      results: $("results"),
      money: $("menu-money"),
      money2: $("menu-best"),
      wins: $("menu-wins"),
      best2: $("menu-best-2"),
      record: $("menu-record"),
      carName: $("menu-car-name"),
      carClass: $("menu-car-class"),
      carStats: $("menu-car-stats"),
      rival: $("menu-rival"),
      rivalLine: $("menu-rival-line"),
      rivalTime: $("menu-rival-time"),
      garageMoney: $("garage-money"),
      carList: $("car-list"),
      paintList: $("paint-list"),
      upgradeList: $("upgrade-list"),
      tree: [$("t1"), $("t2"), $("t3")],
      treeGreen: $("tg"),
      treeRed: $("tr"),
      timer: $("hud-timer"),
      phase: $("hud-phase"),
      speed: $("hud-speed"),
      gear: $("hud-gear"),
      gearHint: $("gear-hint"),
      rpm: $("rpm-fill"),
      dist: $("hud-dist"),
      gapYou: $("gap-you-car"),
      gapRival: $("gap-rival-car"),
      launch: $("launch-prompt"),
      launchBig: document.querySelector(".lp-big"),
      launchLine: document.querySelector(".lp-line"),
      toast: $("hud-toast"),
      foul: $("foul-banner"),
      rivalName: $("hud-rival-name"),
      resTitle: $("res-title"),
      resKicker: $("res-kicker"),
      resSub: $("res-sub"),
      resET: $("res-et"),
      resReaction: $("res-reaction"),
      resSpeed: $("res-speed"),
      resRivalET: $("res-rival-et"),
      resMoney: $("res-money"),
      resRecord: $("res-record"),
      wheelPad: $("wheel-pad"),
      wheelKnob: $("wheel-knob"),
      gas: $("btn-gas"),
      clutch: $("btn-brake"),
      shiftUp: $("btn-shift-up"),
      shiftDown: $("btn-shift-down"),
      sound: $("btn-sound"),
    };
    this.toastTimer = 0;
    this._bindStatic();
  }

  _bindStatic() {
    const g = this.game;
    $("btn-boot").addEventListener("click", () => g.boot());
    $("btn-race").addEventListener("click", () => g.startRace());
    $("btn-garage").addEventListener("click", () => g.openGarage());
    $("btn-garage-2").addEventListener("click", () => g.openGarage());
    $("btn-help").addEventListener("click", () => g.openHelp());
    $("btn-res-again").addEventListener("click", () => g.startRace());
    $("btn-res-garage").addEventListener("click", () => g.openGarage());
    $("btn-res-menu").addEventListener("click", () => g.openMenu());
    $("btn-cam").addEventListener("click", () => g.toggleCamera());
    this.el.sound.addEventListener("click", () => g.toggleSound());
    for (const btn of document.querySelectorAll("[data-close]")) {
      btn.addEventListener("click", () => g.closePanel(btn.dataset.close));
    }
  }

  show(name) {
    const screens = ["boot", "menu", "garage", "help", "results"];
    for (const s of screens) this.el[s].classList.toggle("hidden", s !== name);
    this.el.hud.classList.toggle("hidden", name !== "race");
  }

  updateMenu(save) {
    const car = carById(save.selected);
    const up = save.upgrades[car.id] || {};
    const power = estimatePower(car, up);
    this.el.money.textContent = money(save.money);
    this.el.wins.textContent = save.wins;
    this.el.carName.textContent = car.name;
    this.el.carClass.textContent = car.klass;
    this.el.carStats.innerHTML = `
      <div><b>${power}</b><small>CAVALOS</small></div>
      <div><b>${Math.round(buildSpec(car, up).mass)}</b><small>KG</small></div>
      <div><b>${save.bestET ? fmtTime(save.bestET).replace("s", "") : "—"}</b><small>MELHOR ET</small></div>`;
    this.el.best2.textContent = save.bestET ? fmtTime(save.bestET) : "—";
    this.el.record.textContent = save.races ? `${save.races} corridas · ${save.wins} vitórias` : "sem registro";
    const rival = g_rival(save);
    this.el.rival.textContent = rival.name;
    this.el.rivalLine.textContent = rival.quote;
    this.el.rivalTime.textContent = `ET alvo ${rival.target.toFixed(2)}s`;
    this.el.sound.textContent = save.sound ? "🔊" : "🔇";
  }

  renderGarage(save) {
    const g = this.game;
    this.el.garageMoney.textContent = money(save.money);
    // carros
    this.el.carList.innerHTML = "";
    for (const car of CARS) {
      const owned = save.ownedCars.includes(car.id);
      const active = save.selected === car.id;
      const up = save.upgrades[car.id] || {};
      const power = estimatePower(car, up);
      const row = document.createElement("div");
      row.className = `car-row${active ? " active" : ""}${owned ? "" : " locked"}`;
      row.innerHTML = `
        <div>
          <h4>${car.name} <span class="tag">${car.klass}</span></h4>
          <div class="spec">${power} cv · ${Math.round(buildSpec(car, up).mass)} kg · ${car.tagline}</div>
        </div>
        <div class="car-action ${active ? "equipped" : owned ? "" : "buy"}">
          ${active ? "EM USO" : owned ? "USAR" : money(car.price)}
        </div>`;
      row.addEventListener("click", () => g.selectCar(car.id));
      this.el.carList.appendChild(row);
    }
    // pintura
    this.el.paintList.innerHTML = "";
    const car = carById(save.selected);
    const paintId = save.paints[car.id] || "laranja";
    for (const p of PAINTS) {
      const sw = document.createElement("div");
      sw.className = `paint-swatch${paintId === p.id ? " active" : ""}`;
      sw.style.background = `radial-gradient(circle at 35% 28%, ${lighten(p.hex, 0.35)}, ${p.hex} 58%, ${darken(p.hex, 0.45)})`;
      sw.title = p.name;
      sw.addEventListener("click", () => g.setPaint(car.id, p.id));
      this.el.paintList.appendChild(sw);
    }
    // upgrades
    this.el.upgradeList.innerHTML = "";
    const ups = save.upgrades[car.id] || {};
    for (const upg of UPGRADES) {
      const lvl = ups[upg.id] | 0;
      const max = lvl >= upg.max;
      const cost = upgradeCost(upg, lvl);
      const row = document.createElement("div");
      row.className = "upgrade-row";
      const pips = Array.from({ length: upg.max }, (_, i) => `<i class="${i < lvl ? "on" : ""}"></i>`).join("");
      row.innerHTML = `
        <div class="upgrade-head"><h4>${upg.name}</h4><span class="lvl">NÍVEL ${lvl}/${upg.max}</span></div>
        <div class="pips">${pips}</div>
        <div class="upgrade-foot">
          <div class="upgrade-desc">${upg.desc}<br>${upg.effect}</div>
          <button class="upgrade-btn ${max ? "max" : ""}" ${max ? "disabled" : ""}>
            ${max ? "NO MÁXIMO" : money(cost)}
          </button>
        </div>`;
      if (!max) {
        row.querySelector("button").addEventListener("click", () => g.buyUpgrade(upg.id));
      }
      this.el.upgradeList.appendChild(row);
    }
  }

  showHUD(rivalName) {
    this.show("race");
    this.el.rivalName.textContent = rivalName;
    this.el.foul.classList.add("hidden");
    this.el.launch.classList.add("hidden");
    this.setTree([false, false, false], false, false);
    this.setTimer(0);
    this.setSpeed(0);
    this.setGear(1, "EMBREIE + ACELERE", 0);
    this.setGap(0, 0, 402.336);
    this.setPhase("PREPARE-SE");
    this.toast("");
  }

  setTree(ambers, green, red) {
    this.el.tree.forEach((t, i) => t.classList.toggle("on", !!ambers[i]));
    this.el.treeGreen.classList.toggle("on", !!green);
    this.el.treeRed.classList.toggle("on", !!red);
  }

  setPhase(text) {
    this.el.phase.textContent = text;
  }

  setTimer(t) {
    this.el.timer.textContent = t >= 0 ? t.toFixed(3) : "0.000";
  }

  setSpeed(kmh) {
    this.el.speed.textContent = Math.max(0, Math.round(kmh));
  }

  setGear(gear, hint, rpmNorm) {
    this.el.gear.textContent = gear;
    if (hint != null) this.el.gearHint.textContent = hint;
    this.el.rpm.style.width = `${Math.min(112, rpmNorm * 100)}%`;
  }

  setDist(d) {
    this.el.dist.textContent = Math.max(0, Math.round(402.336 - d));
  }

  setGap(playerDist, rivalDist, finish) {
    const p = Math.max(0, Math.min(1, playerDist / finish));
    const r = Math.max(0, Math.min(1, rivalDist / finish));
    this.el.gapYou.style.left = `${p * 92}%`;
    this.el.gapRival.style.left = `${r * 92}%`;
  }

  showLaunch(show) {
    this.el.launch.classList.toggle("hidden", !show);
  }

  setLaunchText(line, big) {
    this.el.launchLine.textContent = line;
    this.el.launchBig.textContent = big;
  }

  toast(text, ms = 1100) {
    this.el.toast.textContent = text;
    this.el.toast.classList.toggle("show", !!text);
    clearTimeout(this.toastTimer);
    if (text) this.toastTimer = setTimeout(() => this.el.toast.classList.remove("show"), ms);
  }

  showFoul(show) {
    this.el.foul.classList.toggle("hidden", !show);
  }

  setWheel(steer) {
    this.el.wheelPad.style.setProperty("--rot", `${steer * 90}deg`);
    this.el.wheelKnob.style.transform = `translate(${steer * 36}px, 0)`;
  }

  setPedals(throttle, clutch) {
    this.el.gas.classList.toggle("active", throttle > 0.1);
    this.el.clutch.classList.toggle("active", !!clutch);
  }

  showResults(r) {
    this.show("results");
    this.el.results.classList.toggle("lose", !r.win);
    this.el.resTitle.textContent = r.foul ? "QUEIMOU" : r.win ? "VITÓRIA" : "DERROTA";
    this.el.resKicker.textContent = r.foul ? "DESCLASSIFICADO" : r.win ? "RESULTADO OFICIAL" : "RESULTADO OFICIAL";
    this.el.resSub.textContent = r.foul
      ? "Você soltou a embreagem antes do verde. O fiscal não perdoou."
      : r.win
        ? `Você cruzou ${r.margin > 0 ? r.margin.toFixed(3) + "s" : "na frente"} antes do rival.`
        : r.dnf
          ? "O carro não cruzou a linha. Ajuste o setup e tente de novo."
          : `Faltaram ${r.margin.toFixed(3)}s para pegar o ${r.rivalName}.`;
    this.el.resET.textContent = r.et ? r.et.toFixed(3) : "DNF";
    this.el.resReaction.textContent = r.reaction != null ? r.reaction.toFixed(3) + "s" : "—";
    this.el.resSpeed.textContent = Math.round(r.trap || 0);
    this.el.resRivalET.textContent = r.rivalET ? r.rivalET.toFixed(3) : "DNF";
    this.el.resMoney.textContent = (r.prize >= 0 ? "+ " : "− ") + money(Math.abs(r.prize));
    this.el.resMoney.style.color = r.prize >= 0 ? "var(--green)" : "var(--red)";
    this.el.resRecord.classList.toggle("hidden", !r.record);
  }
}

// alvo estimado do próximo rival (usado no menu)
export function g_rival(save) {
  const list = this && this.rivals ? this.rivals : null;
  return list ? list(save) : { name: "ZÉ DO TURBO", quote: "“Essa reta é minha desde 1998, garoto.”", target: 14.5 };
}

function clamp255(v) {
  return Math.max(0, Math.min(255, Math.round(v)));
}
function lighten(hex, amt) {
  const c = hex.replace("#", "");
  const r = clamp255(parseInt(c.slice(0, 2), 16) + 255 * amt);
  const g = clamp255(parseInt(c.slice(2, 4), 16) + 255 * amt);
  const b = clamp255(parseInt(c.slice(4, 6), 16) + 255 * amt);
  return `rgb(${r},${g},${b})`;
}
function darken(hex, amt) {
  const c = hex.replace("#", "");
  const r = clamp255(parseInt(c.slice(0, 2), 16) * (1 - amt));
  const g = clamp255(parseInt(c.slice(2, 4), 16) * (1 - amt));
  const b = clamp255(parseInt(c.slice(4, 6), 16) * (1 - amt));
  return `rgb(${r},${g},${b})`;
}

