354:       const a = 1.02 + Math.sin(t * 0.1) * 0.1;
355:       const r = 7.6;
356:       const target = new THREE.Vector3(px + Math.sin(a) * r, 2.15, pz + Math.cos(a) * r);
357:       cam.position.lerp(target, 1 - Math.exp(-rdt * 2.4));
358:       cam.lookAt(px, 0.78, pz + 0.1);
359:       cam.fov += (52 - cam.fov) * Math.min(1, rdt * 2);
360:       cam.updateProjectionMatrix();
361:       return;
362:     }
363: 
364:     if (this.mode === "result") {
365:       const a = 0.9 + t * 0.12;
366:       const r = 8.6;
367:       cam.position.lerp(new THREE.Vector3(px + Math.sin(a) * r, 2.6, pz + Math.cos(a) * r), 1 - Math.exp(-rdt * 2));
368:       cam.lookAt(px, 0.9, pz + 0.4);
369:       cam.fov += (52 - cam.fov) * Math.min(1, rdt * 2);
370:       cam.updateProjectionMatrix();
371:       return;
372:     }
373: 
374:     // race
375:     const sim = this.playerSim;
376:     this.playerGroup.updateMatrixWorld(true);
377:     const speedN = Math.min(1, sim.speed / 75);
378:     if (this.cameraMode === "chase") {
379:       const back = 7.4 + speedN * 1.8;
380:       const target = this.playerGroup.localToWorld(new THREE.Vector3(0, 2.55 + speedN * 0.2, -back));
381:       cam.position.lerp(target, 1 - Math.exp(-rdt * 5));
382:       const look = this.playerGroup.localToWorld(new THREE.Vector3(0, 1.0, 1.6));
383:       cam.lookAt(look);
384:       cam.fov += (60 + speedN * 16 - cam.fov) * Math.min(1, rdt * 4);
385:       cam.updateProjectionMatrix();
386:       return;
387:     }
388: 
389:     // cockpit
390:     const accel = sim.accel;
391:     const shake = Math.min(0.02, sim.speed * 0.00007 + sim.wheelspin * 0.01);
392:     const base = this.playerGroup.localToWorld(new THREE.Vector3(-0.37, 1.4, -0.02));
393:     base.x += Math.sin(t * 53) * shake;
394:     base.y += Math.sin(t * 61 + 1.3) * shake * 0.7;
395:     base.z += Math.cos(t * 47) * shake * 0.5;
396:     cam.position.copy(base);
397:     const pitch = -0.02 - accel * 0.0035 + Math.sin(t * 44) * shake * 0.35;
398:     const roll = -this.steer * 0.035 * speedN + Math.sin(t * 37) * shake * 0.3;
399:     const yaw = this.steer * 0.05 * speedN;
400:     cam.rotation.set(pitch, Math.PI + yaw, roll, "YXZ");
401:     const fov = 66 + speedN * 17 + Math.min(4, sim.wheelspin * 4);
402:     cam.fov += (fov - cam.fov) * Math.min(1, rdt * 4);
403:     cam.updateProjectionMatrix();
404:   }
