563:     this.simAcc = 0;
564:     this.greenReached = false;
565:     this.greenClock = null;
566:     this.foul = false;
567:     this.playerRunStart = null;
568:     this.playerReaction = null;
569:     this.playerFinished = false;
570:     this.rivalFinished = false;
571:     this.playerET = null;
572:     this.playerTrap = 0;
573:     this.rivalET = null;
574:     this.rivalTrap = 0;
575:     this.endScheduled = null;
576:     this.launchPromptVisible = false;
577:     this.lastClutch = false;
578:     this.smokeAcc = 0;
579:     this.treeBeeped = [false, false, false];
580:     this.greenBeeped = false;
581:     this.treeStart = 1.25 + Math.random() * 0.65;
582:     this.amberTimes = [this.treeStart, this.treeStart + 0.6, this.treeStart + 1.2];
583:     this.greenAt = this.treeStart + 1.72;
584: 
585:     const info = this.nextRival();
586:     this.rivalInfo = info;
587:     this.rivalReaction = 0.15 + Math.random() * 0.13 + Math.max(0, (1 - info.idx / 8)) * 0.05;
588: 
589:     // specs e sims
590:     this.playerSpec = buildSpec(carById(this.save.selected), this.save.upgrades[this.save.selected] || {});
591:     this.playerSim = new DragSim(this.playerSpec);
592:     const rspec = buildSpec(carById(info.car), info.upgrades);
593:     rspec.torque *= info.power;
594:     this.rivalSpec = rspec;
595:     this.rivalSim = new DragSim(rspec);
596: 
597:     // modelos
598:     this.playerSim.reset();
599:     this.playerSim.clutch = true;
600:     this.playerSim.prevClutch = true;
601:     this.playerGroup.position.set(LANE, 0, START_Z);
602:     this.playerModel.setPaint(PAINTS.find((p) => p.id === (this.save.paints[this.save.selected] || "laranja"))?.hex || "#ff5a12");
603:     const rivalEntry = this.rivalModels[info.car];
604:     for (const key of Object.keys(this.rivalModels)) this.rivalModels[key].group.visible = key === info.car;
605:     rivalEntry.model.setPaint(RIVAL_PAINTS[info.idx % RIVAL_PAINTS.length]);
606:     rivalEntry.group.visible = true;
607:     rivalEntry.group.position.set(-LANE, 0, START_Z);
608: 
609:     this.track.setTree({ a: [false, false, false], green: false, red: false });
610:     this.effects.clear();
611:     this.ui.showHUD(info.name);
612:     this.ui.setPhase("PREPARE-SE");
613:     this.ui.setLaunchText("A LUZ VERDE ACENDEU", "ACELERA!");
614:     this.ui.showLaunch(false);
615:     this.ui.showFoul(false);
616:     this.speedlines.style.opacity = "0";
617:     this.steer = 0;
618:     this.steerTarget = 0;
619:   }
