621:   updateTree() {
622:     if (!this.greenReached) {
623:       const t = this.raceClock;
624:       const ambers = this.amberTimes.map((at) => t >= at);
625:       this.track.setTree({ a: ambers, green: false, red: this.foul });
626:       this.ui.setTree(ambers, false, this.foul);
627:       for (let i = 0; i < 3; i++) {
628:         if (!this.treeBeeped[i] && t >= this.amberTimes[i]) {
629:           this.treeBeeped[i] = true;
630:           if (!this.foul) this.audio.beep(620 + i * 45, 0.08, 0.12, "square");
631:         }
632:       }
633:       if (t >= this.treeStart && this.phase === "staging") {
634:         this.phase = "tree";
635:         this.ui.setPhase("LUZES ACESAS");
636:       }
637:       if (t >= this.greenAt) this.onGreen();
638:     } else {
639:       this.track.setTree({ a: [false, false, false], green: !this.foul, red: this.foul });
640:       this.ui.setTree([false, false, false], !this.foul, this.foul);
641:     }
642:   }
643: 
644:   onGreen() {
645:     if (this.greenReached) return;
646:     this.greenReached = true;
647:     this.greenClock = this.raceClock;
648:     this.phase = "racing";
649:     this.ui.setPhase(this.foul ? "QUEIMOU" : "VAI!");
650:     if (!this.foul) {
651:       this.audio.beep(980, 0.25, 0.18, "square");
652:       this.ui.showLaunch(true);
653:       this.ui.setLaunchText("SOLTE A EMBREAGEM E PISA", "VAI!");
654:       this.ui.toast("VERDE! SOLTA A EMBREAGEM", 900);
655:     }
656:   }
657: 
658:   registerFoul() {
659:     this.foul = true;
660:     this.ui.showFoul(true);
661:     this.ui.showLaunch(false);
662:     this.ui.setPhase("QUEIMOU");
663:     this.audio.foul();
664:   }
665: 
666:   stepRace(h) {
667:     if (this.mode !== "race") return;
668:     if (this.phase === "idle") return;
669: 
670:     const pin = !this.greenReached;
671:     const pInput = this.playerInput();
672:     const clutchNow = this.playerClutchPressed();
673: 
674:     if (!this.greenReached && !this.foul && this.lastClutch && !clutchNow && pInput.throttle > 0.15) {
675:       this.registerFoul();
676:     }
677:     this.lastClutch = clutchNow;
678: 
679:     this.playerSim.step(h, pInput, pin);
680:     if (this.autoShift && this.greenReached && !this.playerFinished) {
681:       const before = this.playerSim.gear;
682:       this.playerSim.autoShift();
683:       if (this.playerSim.gear !== before) {
684:         this.audio.pop(0.6);
685:         this.audio.whoosh();
686:         this.spawnBackfire();
687:       }
688:     }
689: 
690:     // rival
691:     const rSim = this.rivalSim;
692:     const locked = !this.greenReached;
693:     const rThrottle = rSim.engineRpm < this.rivalSpec.launchRpm ? 1 : 0.15;
694:     let rInput;
695:     if (locked) {
696:       rInput = { throttle: rThrottle, clutch: true, steer: 0, brake: 0 };
697:     } else if (this.raceClock < this.greenClock + this.rivalReaction) {
698:       rInput = { throttle: rThrottle, clutch: true, steer: 0, brake: 0 };
699:     } else {
700:       const thr = rSim.wheelspin > 0.6 ? 0.65 : 1;
701:       rInput = { throttle: thr, clutch: false, steer: 0, brake: this.rivalFinished ? 1 : 0 };
702:     }
703:     rSim.step(h, rInput, locked);
704:     if (this.greenReached && !this.rivalFinished && !locked) {
705:       const before = rSim.gear;
706:       rSim.autoShift();
707:       if (rSim.gear !== before) this.spawnBackfire(true);
708:     }
709: 
710:     // chegadas
711:     if (!this.playerFinished && this.playerSim.distance >= FINISH) {
712:       this.playerFinished = true;
713:       this.playerFinishClock = this.raceClock;
714:       this.playerET = this.playerRunStart != null ? this.raceClock - this.playerRunStart : null;
715:       this.playerTrap = this.playerSim.speedKmh;
716:       this.ui.toast(`CHEGOU! ${this.playerET ? this.playerET.toFixed(3) + "s" : ""}`, 1600);
717:       this.audio.pop(1);
718:     }
719:     if (!this.rivalFinished && rSim.distance >= FINISH) {
720:       this.rivalFinished = true;
721:       this.rivalFinishClock = this.raceClock;
722:       this.rivalET = this.raceClock - (this.greenClock + this.rivalReaction);
723:       this.rivalTrap = rSim.speedKmh;
724:     }
725:   }
726: 
727:   spawnBackfire(rival = false) {
728:     const model = rival ? this.rivalModels[this.rivalInfo?.car]?.model : this.playerModel;
729:     if (!model) return;
730:     const pos = new THREE.Vector3();
731:     for (const tip of model.exhaustTips) {
732:       tip.getWorldPosition(pos);
733:       this.effects.emitBackfire(pos, new THREE.Vector3(0, 0.2, -1));
734:     }
735:   }
736: 
737:   updateRace(rdt) {
738:     this.raceClock += rdt;
739:     this.updateTree();
740: 
741:     if (this.greenReached && !this.playerRunStart && this.playerSim.speed > 0.25) {
742:       this.playerRunStart = this.raceClock;
743:       this.playerReaction = this.raceClock - this.greenClock;
744:       this.launchPromptVisible = false;
745:       this.ui.showLaunch(false);
746:       if (!this.foul) {
747:         const rt = this.playerReaction;
748:         const label = rt < 0.16 ? "LARGADA PERFEITA" : rt < 0.34 ? "BOA LARGADA" : "SAIU ATRASADO";
749:         this.ui.toast(`${label} · ${rt.toFixed(3)}s`, 1300);
750:         if (rt < 0.16) this.audio.beep(1200, 0.12, 0.1, "triangle");
751:       }
752:     }
753: 
754:     // fim de corrida
755:     if (this.playerFinished && this.rivalFinished && this.endScheduled == null) {
756:       this.endScheduled = this.raceClock;
757:     }
758:     if (this.playerFinished && !this.rivalFinished && this.raceClock - this.playerFinishClock > 5 && this.endScheduled == null) {
759:       this.endScheduled = this.raceClock;
760:     }
761:     if (!this.playerFinished && this.raceClock - this.greenClock > 20 && this.endScheduled == null) {
762:       this.endScheduled = this.raceClock;
763:     }
764:     if (this.endScheduled != null && this.raceClock - this.endScheduled > 1.3) {
765:       this.finishRace();
766:     }
767:   }
768: 
769:   finishRace() {
770:     if (this.mode !== "race") return;
771:     this.mode = "result";
772:     this.cameraMode = "chase";
773:     const totalPlayer = this.playerFinished ? this.playerFinishClock - this.greenClock : Infinity;
774:     const totalRival = this.rivalFinished ? this.rivalFinishClock - this.greenClock : Infinity;
775:     const dnf = !this.playerFinished;
776:     const win = !this.foul && !dnf && totalPlayer < totalRival;
777:     const margin = win
778:       ? Math.max(0, (this.rivalFinished ? totalRival : totalPlayer + 1) - totalPlayer)
779:       : this.rivalFinished ? Math.abs(totalPlayer - totalRival) : 0;
780: 
781:     const info = this.rivalInfo;
782:     let prize = 0;
783:     if (!this.foul && !dnf) prize = win ? info.reward : Math.round(info.reward * 0.2);
784:     const prevBest = this.save.bestET;
785:     const record = !this.foul && !dnf && this.playerET != null && (prevBest == null || this.playerET < prevBest);
786: 
787:     if (!this.foul && !dnf) {
788:       this.save.races++;
789:       if (win) {
790:         this.save.wins++;
791:         this.save.careerWins++;
792:       } else {
793:         this.save.losses++;
794:       }
795:       if (this.playerET != null && (this.save.bestET == null || this.playerET < this.save.bestET)) this.save.bestET = this.playerET;
796:       if (this.playerTrap && (this.save.bestTrap == null || this.playerTrap > this.save.bestTrap)) this.save.bestTrap = this.playerTrap;
797:     } else {
798:       this.save.races++;
799:       this.save.losses++;
800:     }
801:     const champion = win && this.save.careerWins === RIVALS.length;
802:     if (champion) prize += 5000;
803:     this.save.money += prize;
804:     persist(this.save);
805: 
806:     const playedChampion = win && this.save.careerWins >= RIVALS.length;
807:     this.ui.showResults({
808:       win,
809:       foul: this.foul,
810:       dnf,
811:       et: this.playerET,
812:       reaction: this.playerReaction,
813:       trap: this.playerTrap,
814:       rivalET: this.rivalET,
815:       rivalName: info.name,
816:       margin,
817:       prize,
818:       record,
819:       kicker: champion ? "CAMPEÃO DA TEMPORADA" : this.foul ? "DESCLASSIFICADO" : "RESULTADO OFICIAL",
820:       sub: champion
821:         ? "Você limpou a fila inteira. O asfalto agora tem dono — e é você."
822:         : playedChampion && win
823:           ? "O rei caiu de novo. A fila vai ficar brava e voltar mais forte."
824:           : this.foul
825:             ? "Você soltou a embreagem antes do verde. O fiscal não perdoou."
826:             : undefined,
827:     });
828:     if (this.foul) this.audio.foul();
829:     else if (win) this.audio.win();
830:     else this.audio.lose();
831:     this.speedlines.style.opacity = "0";
832:     this.ui.showFoul(false);
833:   }
834: 
835:   // ---------- loop ----------
836:   updateCarVisuals(rdt) {
837:     const p = this.playerModel;
838:     if (p) {
839:       const sim = this.playerSim;
840:       this.playerGroup.position.set(LANE + sim.lateral, 0, START_Z + sim.distance);
841:       const spin = (sim.speed / this.playerSpec.wheelRadius) * rdt;
842:       for (const w of p.wheels) {
843:         w.spin.rotation.x -= spin;
844:         w.steerGroup.rotation.y = w.front ? this.steer * 0.42 : 0;
845:       }
846:       if (p.steeringWheel) p.steeringWheel.rotation.z = this.steer * 1.0;
847:       if (p.needles.tach) p.needles.tach.rotation.z = 2.25 - sim.rpmNorm * 4.5;
848:       if (p.needles.speed) p.needles.speed.rotation.z = 2.25 - Math.min(1, sim.speedKmh / 240) * 4.5;
849: 
850:       // fumaça de pneu
851:       if (sim.wheelspin > 0.38 && Math.random() < sim.wheelspin) {
852:         const pos = new THREE.Vector3();
853:         for (const w of p.wheels) {
854:           if (w.front) continue;
855:           w.group.getWorldPosition(pos);
856:           pos.y = 0.06;
857:           this.effects.emitSmoke(pos, sim.wheelspin);
858:         }
859:       }
860:     }
861: 
862:     if (this.rivalInfo) {
863:       const entry = this.rivalModels[this.rivalInfo.car];
