import { DragSim, QUARTER_MILE } from '../home/runner/work/PlayGround/PlayGround/src/physics.js';
import { CARS, RIVALS, buildSpec, carById } from '../home/runner/work/PlayGround/PlayGround/src/data.js';

const dt = 1 / 120;

function run(spec, launchRpm = spec.launchRpm, shiftAt = 0.97) {
  const sim = new DragSim(spec);
  sim.clutch = true;
  let t = 0;
  // burnout/clutch dump prep
  for (let i = 0; i < 600 && sim.engineRpm < launchRpm; i++) {
    sim.step(dt, { throttle: 1, clutch: true }, true);
    t += dt;
  }
  // green: release clutch, full throttle
  for (let i = 0; i < 120 * 30; i++) {
    const thr = sim.wheelspin > 0.65 ? 0.7 : 1;
    sim.step(dt, { throttle: thr, clutch: false }, false);
    t += dt;
    // manual shifting at redline-ish
    if (sim.rpmNorm > shiftAt) sim.shiftUp();
    if (sim.distance >= QUARTER_MILE) break;
  }
  return { et: t, speed: sim.speedKmh, dist: sim.distance, gear: sim.gear, spin: sim.wheelspin };
