    const p = g.playerGroup.position;
    if (g.playerModel?.windshieldGlass) g.playerModel.windshieldGlass.visible = false;
    if (g.playerModel?.roofParts) for (const m of g.playerModel.roofParts) m.visible = false;
    const c = g.camera;
    c.position.set(p.x - 0.37, 1.4, p.z - 0.02);
    c.rotation.set(-0.02, Math.PI, 0, 'YXZ');
    c.fov = 66; c.updateProjectionMatrix();
  };
});
await page.waitForTimeout(600);

const hits = await page.evaluate(async () => {
  const THREE = await import('/node_modules/three/build/three.module.js');
  const g = window.__dragBrasil;
  const ray = new THREE.Raycaster();

  // name every mesh with a readable path + dimensions
  function pathOf(o) {
    const parts = [];
    let cur = o;
    while (cur && cur !== g.scene) {
      let label = cur.userData.dbg || cur.type;
      if (cur === g.playerModel.root) label = 'PLAYER';
      else if (cur === g.playerModel.body) label = 'body';
      parts.unshift(label);
      cur = cur.parent;
    }
    return parts.join('/');
  }
  const meshes = [];
  g.scene.traverse((o) => {
    if (o.isMesh) {
      o.userData.dbg = `geo:${o.geometry.type}${o.geometry.parameters ? ':' + JSON.stringify(o.geometry.parameters).slice(0, 80) : ''}`;
      meshes.push(o);
    }
  });

  const out = [];
  const pts = [
    ['bar-center', 0, 0.75], ['bar-left', -0.6, 0.74], ['bar-right', 0.6, 0.74],
    ['hood-gray', 0.0, 0.25], ['hood-orange-left', -0.35, 0.2],
    ['dash', 0.1, -0.45], ['horizon', 0, 0],
  ];
  for (const [name, nx, ny] of pts) {
    ray.setFromCamera(new THREE.Vector2(nx, ny), g.camera);
    const hit = ray.intersectObjects(meshes, false)[0];
    out.push({
      name,
      hit: hit ? pathOf(hit.object) : 'none',
      mat: hit ? hit.object.material?.type : null,
      dist: hit ? +hit.distance.toFixed(3) : null,
      point: hit ? hit.point.toArray().map((v) => +v.toFixed(2)) : null,
    });
  }
  return out;
});
