const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(900);
await page.click('#btn-boot');
await page.waitForTimeout(700);

const report = await page.evaluate(async () => {
  const THREE = await import('/node_modules/three/build/three.module.js');
  const g = window.__dragBrasil;
  g.startRace();
  const body = g.playerModel.body;
  const colors = [0xff0000, 0x00ff00, 0x0000ff, 0xff00ff, 0xffff00, 0x00ffff, 0xff8800, 0x8800ff, 0xffffff];
  const labeled = [];
  // label direct children meshes of body in creation order
  let i = 0;
  for (const child of body.children) {
    if (child.isMesh) {
      const m = child.material.clone();
      m.color.setHex(colors[i % colors.length]);
      m.emissive?.setHex(colors[i % colors.length]);
      if ('emissiveIntensity' in m) m.emissiveIntensity = 0.4;
      child.material = m;
      child.userData.label = `mesh${i}:${child.geometry.type}:${child.position.toArray().map(v => v.toFixed(2)).join(',')}`;
      labeled.push(child.userData.label);
      i++;
    } else if (child.isGroup) {
      child.userData.label = `group${i}:${child.position.toArray().map(v => v.toFixed(2)).join(',')}`;
      labeled.push(child.userData.label);
      i++;
    }
  }
  g.updateCamera = () => {
    const p = g.playerGroup.position;
    if (g.playerModel?.roofParts) for (const m of g.playerModel.roofParts) m.visible = false;
    const c = g.camera;
    c.position.set(p.x - 0.37, 1.4, p.z - 0.02);
    c.up.set(0, 1, 0);
    c.lookAt(p.x - 0.37, 1.31, p.z + 30);
    c.fov = 66; c.updateProjectionMatrix();
  };
  return labeled;
});
console.log(report.join('\n'));
await page.waitForTimeout(800);
await page.screenshot({ path: join(out, '30-colorcoded.png') });

const hits = await page.evaluate(async () => {
  const THREE = await import('/node_modules/three/build/three.module.js');
  const g = window.__dragBrasil;
  g.camera.updateMatrixWorld(true);
  const ray = new THREE.Raycaster();
  const meshes = [];
  g.playerModel.root.traverse((o) => { if (o.isMesh && o.visible) meshes.push(o); });
  const out = [];
  const pts = [['top-bar', 0, 0.75], ['top-bar2', 0, 0.68], ['upper-strip', 0, 0.35], ['mid-strip', 0, 0.22], ['lower', 0, -0.1], ['center', 0, 0]];
  for (const [name, nx, ny] of pts) {
    ray.setFromCamera(new THREE.Vector2(nx, ny), g.camera);
    const hit = ray.intersectObjects(meshes, false)[0];
    const chain = [];
    let cur = hit?.object;
    while (cur && cur !== g.playerModel.root) { chain.unshift(cur.userData.label || cur.type); cur = cur.parent; }
    out.push({ name, hit: hit ? chain.join('>') : 'none', dist: hit ? +hit.distance.toFixed(2) : null, point: hit ? hit.point.toArray().map(v => +v.toFixed(2)) : null });
  }
  return { rot: g.camera.rotation.toArray(), pos: g.camera.position.toArray(), hits: out };
});
console.log(JSON.stringify(hits, null, 1));
await browser.close();

