import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(900);
await page.click('#btn-boot');
await page.waitForTimeout(700);
await page.click('#btn-race');
await page.waitForTimeout(900);

const diag = await page.evaluate(async () => {
  const THREE = await import('/node_modules/three/build/three.module.js');
  const g = window.__dragBrasil;
  g.camera.updateMatrixWorld(true);
  const cam = g.camera;

  // find tree group
  const treeGroup = g.track.group.children.find((c) => c.type === 'Group' && Math.abs(c.position.z - 11.5) < 0.01 && Math.abs(c.position.x) < 0.01);
  const treeInfo = treeGroup ? { pos: treeGroup.position.toArray(), scale: treeGroup.scale.toArray(), children: treeGroup.children.length } : null;

  function project(v) {
    const p = v.clone().project(cam);
    return { ndc: [+p.x.toFixed(3), +p.y.toFixed(3), +p.z.toFixed(3)], px: [Math.round((p.x + 1) / 2 * innerWidth), Math.round((1 - p.y) / 2 * innerHeight)] };
  }
  const bulbs = treeGroup ? treeGroup.children.filter((c) => c.isMesh && c.geometry.type === 'SphereGeometry') : [];
  const bulbScreens = bulbs.map((b) => {
    const wp = b.getWorldPosition(new THREE.Vector3());
    return { wp: wp.toArray().map((v) => +v.toFixed(2)), ...project(wp) };
  });

  // raycast screen points
  const ray = new THREE.Raycaster();
  const targets = g.scene.children;
  function labelOf(o) {
    const chain = [];
    let cur = o;
    while (cur && cur !== g.scene) { chain.unshift(cur.userData.dbg || cur.type); cur = cur.parent; }
    return chain.join('>');
  }
  const pts = [
    ['grey-slab', 640, 430], ['grey-slab2', 900, 470], ['black-band', 640, 555],
    ['orange-hood', 640, 320], ['scoop', 400, 315], ['top-left-black', 90, 30],
    ['right-pillar', 900, 150], ['left-pillar', 150, 200], ['center-road', 700, 250],
  ];
  const hits = [];
  for (const [name, px, py] of pts) {
    const ndc = new THREE.Vector2((px / innerWidth) * 2 - 1, -(py / innerHeight) * 2 + 1);
    ray.setFromCamera(ndc, cam);
    const hit = ray.intersectObjects(targets, true)[0];
    hits.push({ name, px, py, hit: hit ? labelOf(hit.object) : 'none', dist: hit ? +hit.distance.toFixed(2) : null, point: hit ? hit.point.toArray().map((v) => +v.toFixed(2)) : null });
  }

  // project player car parts
  const pbody = g.playerModel.body;
  const named = ['hood', 'dash', 'dashTop', 'cowl'];
  return {
    treeInfo, bulbScreens,
    cam: { pos: cam.position.toArray(), rot: cam.rotation.toArray(), fov: cam.fov },
    playerPos: g.playerGroup.position.toArray(),
    hits,
    trackChildren: g.track.group.children.filter((c) => c.type === 'Group').map((c) => ({ pos: c.position.toArray(), n: c.children.length })).slice(0, 8),
  };
});
console.log(JSON.stringify(diag, null, 1));
await page.screenshot({ path: join(out, '50-diag.png') });
await browser.close();

