await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(900);
await page.click('#btn-boot');
await page.waitForTimeout(700);
await page.click('#btn-race');
await page.waitForTimeout(700);
const out = await page.evaluate(async () => {
  const THREE = await import('/node_modules/three/build/three.module.js');
  const g = window.__dragBrasil;
  const cam = g.camera;
  cam.updateMatrixWorld(true);
  // label player meshes
  let idx = 0;
  g.playerModel.body.traverse((o) => {
    if (o.isMesh) {
      o.userData.dbg = `m${idx} ${o.geometry.type} ` + (o.geometry.parameters ? JSON.stringify(o.geometry.parameters).slice(0, 70) : '') + ` @${o.position.toArray().map(v => v.toFixed(2)).join(',')} visible=${o.visible}`;
      idx++;
    }
  });
  const targets = [];
  g.scene.traverse((o) => {
    if (!o.isMesh) return;
    let vis = true;
    for (let cur = o; cur; cur = cur.parent) if (cur.visible === false) { vis = false; break; }
    if (vis) targets.push(o);
  });
  const ray = new THREE.Raycaster();
  const pts = [[90, 30], [900, 40], [900, 150], [640, 500], [640, 560], [1000, 330], [500, 430]];
  const hits = pts.map(([px, py]) => {
    const ndc = new THREE.Vector2((px / innerWidth) * 2 - 1, -(py / innerHeight) * 2 + 1);
    ray.setFromCamera(ndc, cam);
    const hit = ray.intersectObjects(targets, false)[0];
    const chain = [];
    let cur = hit?.object;
    while (cur && cur !== g.scene) { chain.unshift(cur.userData.dbg || cur.type); cur = cur.parent; }
    return { px, py, hit: chain.join(' > '), dist: hit ? +hit.distance.toFixed(2) : null, point: hit ? hit.point.toArray().map(v => +v.toFixed(2)) : null };
  });
  const mirror = g.playerModel.body.children.find((c) => c.geometry?.parameters?.width === 0.26);
  return { hits, mirror: mirror ? { pos: mirror.position.toArray(), params: mirror.geometry.parameters } : null };
});
console.log(JSON.stringify(out, null, 1));
await browser.close();

