import { DragSim, QUARTER_MILE } from '/home/runner/work/PlayGround/PlayGround/src/physics.js';
import { CARS, RIVALS, buildSpec, carById } from '/home/runner/work/PlayGround/PlayGround/src/data.js';

const dt = 1 / 120;
const RIVAL_POWER = [0.78, 0.87, 0.95, 1.0, 1.05, 1.1, 1.15, 1.22];

function target(spec) {
  const sim = new DragSim(spec);
  for (let i = 0; i < 240; i++) {
    const thr = sim.engineRpm < spec.launchRpm ? 1 : 0.15;
    sim.step(dt, { throttle: thr, clutch: true }, true);
    if (sim.engineRpm >= spec.launchRpm) break;
  }
  let t = 0, guard = 0;
  while (sim.distance < QUARTER_MILE && guard++ < 120 * 22) {
    const thr = sim.wheelspin > 0.6 ? 0.65 : 1;
    sim.step(dt, { throttle: thr, clutch: false }, false);
    sim.autoShift();
    t += dt;
  }
  return t;
}

function player(spec) {
  const sim = new DragSim(spec);
  sim.clutch = true;
  let t = 0;
  // stage: build revs to launchRpm while clutch in
  for (let i = 0; i < 480; i++) {
    sim.step(dt, { throttle: 1, clutch: true }, true);
    if (sim.engineRpm >= spec.launchRpm) break;
  }
  // release at green, full throttle, auto shift
  for (let i = 0; i < 120 * 20; i++) {
    const thr = sim.wheelspin > 0.6 ? 0.7 : 1;
    sim.step(dt, { throttle: thr, clutch: false }, false);
    sim.autoShift();
    t += dt;
    if (sim.distance >= QUARTER_MILE) break;
  }
  return { et: t, trap: sim.speedKmh };
}

const stock = buildSpec(carById('falcao'), {});
console.log('player stock with ideal launch', player(stock));
console.log('player stock with auto target style', target(stock));
for (let i = 0; i < RIVALS.length; i++) {
  const info = RIVALS[i];
  const spec = buildSpec(carById(info.car), info.upgrades);
  spec.torque *= RIVAL_POWER[i];
  console.log(i + 1, info.name, 'target', target(spec).toFixed(3), 'power', RIVAL_POWER[i]);
}
// player with engine 1 tires 1
const tuned = buildSpec(carById('falcao'), { engine: 1, tires: 1 });
console.log('player tuned e1 t1 ideal', player(tuned));

