557:   // ---------- corrida ----------
558:   startRace() {
559:     this.audio.init();
560:     this.audio.ui();
561:     this.mode = "race";
562:     this.phase = "staging";
563:     this.cameraMode = "cockpit";
564:     this.raceClock = 0;
565:     this.simAcc = 0;
566:     this.greenReached = false;
567:     this.greenClock = null;
568:     this.foul = false;
569:     this.playerRunStart = null;
570:     this.playerReaction = null;
571:     this.playerFinished = false;
572:     this.rivalFinished = false;
573:     this.playerET = null;
574:     this.playerTrap = 0;
575:     this.rivalET = null;
576:     this.rivalTrap = 0;
577:     this.endScheduled = null;
578:     this.launchPromptVisible = false;
579:     this.lastClutch = false;
580:     this.smokeAcc = 0;
581:     this.treeBeeped = [false, false, false];
582:     this.greenBeeped = false;
583:     this.treeStart = 1.25 + Math.random() * 0.65;
584:     this.amberTimes = [this.treeStart, this.treeStart + 0.6, this.treeStart + 1.2];
585:     this.greenAt = this.treeStart + 1.72;
586: 
587:     const info = this.nextRival();
588:     this.rivalInfo = info;
589:     this.rivalReaction = 0.15 + Math.random() * 0.13 + Math.max(0, (1 - info.idx / 8)) * 0.05;
590: 
591:     // specs e sims
592:     this.playerSpec = buildSpec(carById(this.save.selected), this.save.upgrades[this.save.selected] || {});
593:     this.playerSim = new DragSim(this.playerSpec);
594:     const rspec = buildSpec(carById(info.car), info.upgrades);
595:     rspec.torque *= info.power;
596:     this.rivalSpec = rspec;
597:     this.rivalSim = new DragSim(rspec);
598: 
599:     // modelos
600:     this.playerSim.reset();
601:     this.playerSim.clutch = true;
602:     this.playerSim.prevClutch = true;
603:     this.playerGroup.position.set(LANE, 0, START_Z);
604:     this.playerModel.setPaint(PAINTS.find((p) => p.id === (this.save.paints[this.save.selected] || "laranja"))?.hex || "#ff5a12");
605:     const rivalEntry = this.rivalModels[info.car];
606:     for (const key of Object.keys(this.rivalModels)) this.rivalModels[key].group.visible = key === info.car;
607:     rivalEntry.model.setPaint(RIVAL_PAINTS[info.idx % RIVAL_PAINTS.length]);
608:     rivalEntry.group.visible = true;
609:     rivalEntry.group.position.set(-LANE, 0, START_Z);
610: 
611:     this.track.setTree({ a: [false, false, false], green: false, red: false });
612:     this.effects.clear();
613:     this.ui.showHUD(info.name);
614:     this.ui.setPhase("PREPARE-SE");
615:     this.ui.setLaunchText("A LUZ VERDE ACENDEU", "ACELERA!");
616:     this.ui.showLaunch(false);
617:     this.ui.showFoul(false);
618:     this.speedlines.style.opacity = "0";
619:     this.steer = 0;
620:     this.steerTarget = 0;
621:   }
622: 
623:   updateTree() {
624:     if (!this.greenReached) {
625:       const t = this.raceClock;
626:       const ambers = this.amberTimes.map((at) => t >= at);
627:       this.track.setTree({ a: ambers, green: false, red: this.foul });
628:       this.ui.setTree(ambers, false, this.foul);
629:       for (let i = 0; i < 3; i++) {
630:         if (!this.treeBeeped[i] && t >= this.amberTimes[i]) {
631:           this.treeBeeped[i] = true;
632:           if (!this.foul) this.audio.beep(620 + i * 45, 0.08, 0.12, "square");
633:         }
634:       }
635:       if (t >= this.treeStart && this.phase === "staging") {
636:         this.phase = "tree";
637:         this.ui.setPhase("LUZES ACESAS");
638:       }
639:       if (t >= this.greenAt) this.onGreen();
640:     } else {
641:       this.track.setTree({ a: [false, false, false], green: !this.foul, red: this.foul });
642:       this.ui.setTree([false, false, false], !this.foul, this.foul);
643:     }
644:   }
645: 
646:   onGreen() {
647:     if (this.greenReached) return;
648:     this.greenReached = true;
649:     this.greenClock = this.raceClock;
650:     this.phase = "racing";
651:     this.ui.setPhase(this.foul ? "QUEIMOU" : "VAI!");
652:     if (!this.foul) {
653:       this.audio.beep(980, 0.25, 0.18, "square");
654:       this.ui.showLaunch(true);
655:       this.ui.setLaunchText("SOLTE A EMBREAGEM E PISA", "VAI!");
656:       this.ui.toast("VERDE! SOLTA A EMBREAGEM", 900);
657:     }
658:   }
659: 
660:   registerFoul() {
661:     this.foul = true;
662:     this.ui.showFoul(true);
663:     this.ui.showLaunch(false);
664:     this.ui.setPhase("QUEIMOU");
665:     this.audio.foul();
666:   }
667: 
668:   stepRace(h) {
669:     if (this.mode !== "race") return;
670:     if (this.phase === "idle") return;
671: 
672:     const pin = !this.greenReached;
673:     const pInput = this.playerInput();
674:     const clutchNow = this.playerClutchPressed();
675: 
676:     if (!this.greenReached && !this.foul && this.lastClutch && !clutchNow && pInput.throttle > 0.15) {
677:       this.registerFoul();
678:     }
679:     this.lastClutch = clutchNow;
680: 
681:     this.playerSim.step(h, pInput, pin);
682:     if (this.autoShift && this.greenReached && !this.playerFinished) {
683:       const before = this.playerSim.gear;
684:       this.playerSim.autoShift();
685:       if (this.playerSim.gear !== before) {
686:         this.audio.pop(0.6);
687:         this.audio.whoosh();
688:         this.spawnBackfire();
689:       }
690:     }
691: 
692:     // rival
693:     const rSim = this.rivalSim;
694:     const locked = !this.greenReached;
695:     const rThrottle = rSim.engineRpm < this.rivalSpec.launchRpm ? 1 : 0.15;
696:     let rInput;
697:     if (locked) {
698:       rInput = { throttle: rThrottle, clutch: true, steer: 0, brake: 0 };
699:     } else if (this.raceClock < this.greenClock + this.rivalReaction) {
700:       rInput = { throttle: rThrottle, clutch: true, steer: 0, brake: 0 };
701:     } else {
702:       const thr = rSim.wheelspin > 0.6 ? 0.65 : 1;
703:       rInput = { throttle: thr, clutch: false, steer: 0, brake: this.rivalFinished ? 1 : 0 };
704:     }
705:     rSim.step(h, rInput, locked);
706:     if (this.greenReached && !this.rivalFinished && !locked) {
707:       const before = rSim.gear;
708:       rSim.autoShift();
709:       if (rSim.gear !== before) this.spawnBackfire(true);
710:     }
711: 
712:     // chegadas
713:     if (!this.playerFinished && this.playerSim.distance >= FINISH) {
714:       this.playerFinished = true;
715:       this.playerFinishClock = this.raceClock;
716:       this.playerET = this.playerRunStart != null ? this.raceClock - this.playerRunStart : null;
717:       this.playerTrap = this.playerSim.speedKmh;
718:       this.ui.toast(`CHEGOU! ${this.playerET ? this.playerET.toFixed(3) + "s" : ""}`, 1600);
719:       this.audio.pop(1);
720:     }
721:     if (!this.rivalFinished && rSim.distance >= FINISH) {
722:       this.rivalFinished = true;
723:       this.rivalFinishClock = this.raceClock;
724:       this.rivalET = this.raceClock - (this.greenClock + this.rivalReaction);
725:       this.rivalTrap = rSim.speedKmh;
726:     }
727:   }
728: 
729:   spawnBackfire(rival = false) {
730:     const model = rival ? this.rivalModels[this.rivalInfo?.car]?.model : this.playerModel;
731:     if (!model) return;
732:     const pos = new THREE.Vector3();
733:     for (const tip of model.exhaustTips) {
734:       tip.getWorldPosition(pos);
735:       this.effects.emitBackfire(pos, new THREE.Vector3(0, 0.2, -1));
736:     }
737:   }
738: 
739:   updateRace(rdt) {
740:     this.raceClock += rdt;
741:     this.updateTree();
742: 
743:     if (this.greenReached && !this.playerRunStart && this.playerSim.speed > 0.25) {
744:       this.playerRunStart = this.raceClock;
745:       this.playerReaction = this.raceClock - this.greenClock;
746:       this.launchPromptVisible = false;
747:       this.ui.showLaunch(false);
748:       if (!this.foul) {
749:         const rt = this.playerReaction;
750:         const label = rt < 0.16 ? "LARGADA PERFEITA" : rt < 0.34 ? "BOA LARGADA" : "SAIU ATRASADO";
751:         this.ui.toast(`${label} · ${rt.toFixed(3)}s`, 1300);
752:         if (rt < 0.16) this.audio.beep(1200, 0.12, 0.1, "triangle");
753:       }
754:     }
755: 
756:     // fim de corrida
757:     if (this.playerFinished && this.rivalFinished && this.endScheduled == null) {
758:       this.endScheduled = this.raceClock;
759:     }
760:     if (this.playerFinished && !this.rivalFinished && this.raceClock - this.playerFinishClock > 5 && this.endScheduled == null) {
761:       this.endScheduled = this.raceClock;
762:     }
763:     if (!this.playerFinished && this.raceClock - this.greenClock > 20 && this.endScheduled == null) {
764:       this.endScheduled = this.raceClock;
765:     }
766:     if (this.endScheduled != null && this.raceClock - this.endScheduled > 1.3) {
767:       this.finishRace();
768:     }
769:   }
770: 
771:   finishRace() {
772:     if (this.mode !== "race") return;
773:     this.mode = "result";
774:     this.cameraMode = "chase";
775:     const totalPlayer = this.playerFinished ? this.playerFinishClock - this.greenClock : Infinity;
776:     const totalRival = this.rivalFinished ? this.rivalFinishClock - this.greenClock : Infinity;
777:     const dnf = !this.playerFinished;
778:     const win = !this.foul && !dnf && totalPlayer < totalRival;
779:     const margin = win
780:       ? Math.max(0, (this.rivalFinished ? totalRival : totalPlayer + 1) - totalPlayer)
781:       : this.rivalFinished ? Math.abs(totalPlayer - totalRival) : 0;
782: 
783:     const info = this.rivalInfo;
784:     let prize = 0;
785:     if (!this.foul && !dnf) prize = win ? info.reward : Math.round(info.reward * 0.2);
786:     const prevBest = this.save.bestET;
787:     const record = !this.foul && !dnf && this.playerET != null && (prevBest == null || this.playerET < prevBest);
788: 
789:     if (!this.foul && !dnf) {
790:       this.save.races++;
791:       if (win) {
792:         this.save.wins++;
793:         this.save.careerWins++;
794:       } else {
795:         this.save.losses++;
796:       }
797:       if (this.playerET != null && (this.save.bestET == null || this.playerET < this.save.bestET)) this.save.bestET = this.playerET;
798:       if (this.playerTrap && (this.save.bestTrap == null || this.playerTrap > this.save.bestTrap)) this.save.bestTrap = this.playerTrap;
799:     } else {
800:       this.save.races++;
801:       this.save.losses++;
802:     }
803:     const champion = win && this.save.careerWins === RIVALS.length;
804:     if (champion) prize += 5000;
805:     this.save.money += prize;
806:     persist(this.save);
807: 
808:     const playedChampion = win && this.save.careerWins >= RIVALS.length;
809:     this.ui.showResults({
810:       win,
811:       foul: this.foul,
812:       dnf,
813:       et: this.playerET,
814:       reaction: this.playerReaction,
815:       trap: this.playerTrap,
816:       rivalET: this.rivalET,
817:       rivalName: info.name,
818:       margin,
819:       prize,
820:       record,
821:       kicker: champion ? "CAMPEÃO DA TEMPORADA" : this.foul ? "DESCLASSIFICADO" : "RESULTADO OFICIAL",
822:       sub: champion
823:         ? "Você limpou a fila inteira. O asfalto agora tem dono — e é você."
824:         : playedChampion && win
825:           ? "O rei caiu de novo. A fila vai ficar brava e voltar mais forte."
826:           : this.foul
827:             ? "Você soltou a embreagem antes do verde. O fiscal não perdoou."
828:             : undefined,
829:     });
830:     if (this.foul) this.audio.foul();
831:     else if (win) this.audio.win();
832:     else this.audio.lose();
833:     this.speedlines.style.opacity = "0";
834:     this.ui.showFoul(false);
835:   }
