837:   // ---------- loop ----------
838:   updateCarVisuals(rdt) {
839:     const p = this.playerModel;
840:     if (p) {
841:       const sim = this.playerSim;
842:       this.playerGroup.position.set(LANE + sim.lateral, 0, START_Z + sim.distance);
843:       const spin = (sim.speed / this.playerSpec.wheelRadius) * rdt;
844:       for (const w of p.wheels) {
845:         w.spin.rotation.x -= spin;
846:         w.steerGroup.rotation.y = w.front ? this.steer * 0.42 : 0;
847:       }
848:       if (p.steeringWheel) p.steeringWheel.rotation.z = this.steer * 1.0;
849:       if (p.needles.tach) p.needles.tach.rotation.z = 2.25 - sim.rpmNorm * 4.5;
850:       if (p.needles.speed) p.needles.speed.rotation.z = 2.25 - Math.min(1, sim.speedKmh / 240) * 4.5;
851: 
852:       // fumaça de pneu
853:       if (sim.wheelspin > 0.38 && Math.random() < sim.wheelspin) {
854:         const pos = new THREE.Vector3();
855:         for (const w of p.wheels) {
856:           if (w.front) continue;
857:           w.group.getWorldPosition(pos);
858:           pos.y = 0.06;
859:           this.effects.emitSmoke(pos, sim.wheelspin);
860:         }
861:       }
862:     }
863: 
864:     if (this.rivalInfo) {
865:       const entry = this.rivalModels[this.rivalInfo.car];
866:       if (entry && entry.group.visible) {
867:         const rsim = this.rivalSim;
868:         entry.group.position.set(-LANE + rsim.lateral, 0, START_Z + rsim.distance);
869:         const spin = (rsim.speed / this.rivalSpec.wheelRadius) * rdt;
870:         for (const w of entry.model.wheels) w.spin.rotation.x -= spin;
871:         if (rsim.wheelspin > 0.4 && Math.random() < rsim.wheelspin * 0.7) {
872:           const pos = new THREE.Vector3();
873:           for (const w of entry.model.wheels) {
874:             if (w.front) continue;
875:             w.group.getWorldPosition(pos);
876:             pos.y = 0.05;
877:             this.effects.emitSmoke(pos, rsim.wheelspin * 0.8);
878:           }
879:         }
880:       }
881:     }
882: 
883:     // luz de freio
884:     const braking = this.mode === "race" && (this.playerFinished || this.playerSim.brake > 0.1);
885:     // material compartilhado: acende as lanternas de todos os carros
886:     if (p) {
887:       p.root.traverse((o) => {
888:         if (o.isMesh && o.material && o.material.emissive && o.material.emissive.r > 0.5 && o.material.emissive.g < 0.2) {
889:           o.material.emissiveIntensity = braking ? 3.2 : 0.9;
890:         }
891:       });
892:     }
893:   }
