895:   updateHud() {
896:     const sim = this.playerSim;
897:     if (!sim) return;
898:     this.ui.setSpeed(sim.speedKmh);
899:     let hint = "SEGURE O GÁS";
900:     let phase = this.ui.el.phase.textContent;
901:     if (this.mode === "race") {
902:       if (!this.greenReached) {
903:         hint = "EMBREIE + ACELERE";
904:         this.ui.setPhase(this.foul ? "QUEIMOU" : this.phase === "tree" ? "LUZES ACESAS" : "PREPARE-SE");
905:       } else if (this.playerFinished) {
906:         hint = "FIM";
907:         this.ui.setPhase("FIM");
908:       } else if (!this.playerRunStart) {
909:         hint = "SOLTE A EMBREAGEM";
910:         this.ui.setPhase(this.foul ? "QUEIMOU" : "VAI!");
911:         const showPrompt = !this.foul && this.playerSim.speed < 0.25;
912:         this.ui.showLaunch(showPrompt);
913:         if (showPrompt) {
914:           this.ui.setLaunchText("SOLTE A EMBREAGEM E PISA", "VAI!");
915:         }
916:       } else {
917:         hint = sim.wheelspin > 0.66 ? "PNEU CANTANDO" : this.autoShift ? "CÂMBIO AUTO" : sim.rpmNorm > 0.82 ? "▲ TROCA A MARCHA" : "SEGURE O GÁS";
918:         this.ui.setPhase("CORRIDA");
919:       }
920:     }
921:     this.ui.setGear(sim.gear, hint, sim.rpmNorm);
922:     this.ui.setTimer(this.playerRunStart ? (this.playerFinished ? this.playerET : this.raceClock - this.playerRunStart) : 0);
923:     this.ui.setDist(sim.distance);
924:     if (this.rivalSim) this.ui.setGap(sim.distance, this.rivalSim.distance, FINISH);
925:     this.ui.setPedals(this.touchGas || this.keys.KeyW || this.keys.ArrowUp, this.playerClutchPressed());
926:     this.ui.setWheel(this.steer);
927: 
928:     const kmh = sim.speedKmh;
929:     const op = this.mode === "race" ? clamp((kmh - 75) / 150, 0, 0.55) : 0;
930:     this.speedlines.style.opacity = String(op);
931:   }
