933:   frame(now) {
934:     const rdt = Math.min(0.05, Math.max(0.0001, (now - this.last) / 1000));
935:     this.last = now;
936:     this.time += rdt;
937: 
938:     // input de direção suave
939:     const keyboardSteer =
940:       (this.keys.ArrowRight || this.keys.KeyD ? 1 : 0) + (this.keys.ArrowLeft || this.keys.KeyA ? -1 : 0);
941:     const target = keyboardSteer !== 0 ? keyboardSteer : this.steerTarget;
942:     this.steer += (target - this.steer) * Math.min(1, rdt * 9);
943:     if (Math.abs(this.steer) < 0.002) this.steer = 0;
944: 
945:     if (this.mode === "race") {
946:       this.updateRace(rdt);
947:       this.simAcc += rdt;
948:       let steps = 0;
949:       while (this.simAcc >= dt && steps < 10) {
950:         this.stepRace(dt);
951:         this.simAcc -= dt;
952:         steps++;
953:       }
954:     }
955: 
956:     this.updateCarVisuals(rdt);
957:     this.updateCamera(rdt);
958:     this.effects.update(rdt);
959:     this.track.update(this.time);
