import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const runtime = join(process.env.HOME, ".local/share/omgithub-playwright");
const require = createRequire(join(runtime, "package.json"));
const { chromium } = require("playwright");

const config = JSON.parse(readFileSync(join(runtime, "linux.json"), "utf8"));
process.env.DISPLAY ||= ":" + readFileSync(join(runtime, "display"), "utf8").trim();

const BASE = process.env.APP_URL || "http://localhost:3002";
const OUT = "/home/runner/work/PlayGround/PlayGround/screenshots";

const errors = [];
const consoleErrors = [];

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await context.newPage();
page.setDefaultTimeout(20000);
page.on("pageerror", (e) => errors.push(e.stack || e.message));
page.on("console", (m) => {
  if (m.type() === "error") consoleErrors.push(m.text());
});

const shot = async (name) => {
  await page.screenshot({ path: join(OUT, `verify-${name}.jpg`), type: "jpeg", quality: 78 });
  console.log("shot", name);
};

try {
  const resp = await page.goto(BASE, { waitUntil: "load", timeout: 45000 });
  console.log("HTTP", resp?.status());
  await page.waitForSelector("#btn-boot", { state: "visible" });
  await page.waitForTimeout(600);
  await shot("01-boot");

  await page.click("#btn-boot");
  await page.waitForSelector("#menu:not(.hidden)", { state: "visible" });
  await page.waitForTimeout(900);
  await shot("02-menu");

  const menu = await page.evaluate(() => ({
    money: document.getElementById("menu-money").textContent,
    rival: document.getElementById("menu-rival").textContent,
    car: document.getElementById("menu-car-name").textContent,
    mode: window.__dragBrasil.mode,
  }));
  console.log("MENU", JSON.stringify(menu));

  // garage + economy
  await page.click("#btn-garage");
  await page.waitForSelector("#garage:not(.hidden)", { state: "visible" });
  await page.waitForTimeout(700);
  await shot("03-garage");
  const garage = await page.evaluate(() => ({
    cars: document.querySelectorAll("#car-list .car-row").length,
    upgrades: document.querySelectorAll("#upgrade-list .upgrade-row").length,
    money: document.querySelector("#garage-money").textContent,
  }));
  console.log("GARAGE", JSON.stringify(garage));

  const before = await page.evaluate(() => window.__dragBrasil.save.money);
  await page.click("#upgrade-list .upgrade-row:first-child .upgrade-btn");
  await page.waitForTimeout(350);
  const after = await page.evaluate(() => ({
    money: window.__dragBrasil.save.money,
    engine: window.__dragBrasil.save.upgrades.falcao.engine,
  }));
  console.log("UPGRADE", JSON.stringify({ before, ...after }));
  await shot("04-garage-upgraded");

  await page.click("#garage .btn-back");
  await page.waitForSelector("#menu:not(.hidden)");
  await page.waitForTimeout(400);

  // paint change
  await page.click("#btn-garage");
  await page.waitForSelector("#garage:not(.hidden)");
  await page.click("#paint-list .paint-swatch:nth-child(4)");
  await page.waitForTimeout(300);
  const paint = await page.evaluate(() => window.__dragBrasil.save.paints.falcao);
  console.log("PAINT", paint);
  await page.click("#garage .btn-back");
  await page.waitForSelector("#menu:not(.hidden)");

  // race
  await page.click("#btn-race");
  await page.waitForSelector("#hud:not(.hidden)");
  const raceStart = await page.evaluate(() => ({ mode: window.__dragBrasil.mode, target: window.__dragBrasil.rivalInfo.target }));
  console.log("RACE START", JSON.stringify(raceStart));

  // stage: throttle + clutch to build revs
  await page.keyboard.down("ArrowUp");
  await page.keyboard.down("s");
  await page.waitForTimeout(500);
  const staging = await page.evaluate(() => ({
    rpm: Math.round(window.__dragBrasil.playerSim.engineRpm),
    dist: window.__dragBrasil.playerSim.distance,
    phase: window.__dragBrasil.phase,
  }));
  console.log("STAGING", JSON.stringify(staging));
  await shot("05-staging");

  // launch at green
  await page.waitForFunction(() => document.getElementById("tg").classList.contains("on"), null, { timeout: 12000 });
  await page.keyboard.up("s");
  console.log("GREEN released clutch");
  await page.waitForTimeout(1500);
  await shot("06-cockpit-race");
  const mid = await page.evaluate(() => ({
    speed: Math.round(window.__dragBrasil.playerSim.speedKmh),
    dist: +window.__dragBrasil.playerSim.distance.toFixed(1),
    gear: window.__dragBrasil.playerSim.gear,
    mode: window.__dragBrasil.cameraMode,
    foul: window.__dragBrasil.foul,
  }));
  console.log("MID", JSON.stringify(mid));

  await page.keyboard.press("c");
  await page.waitForTimeout(900);
  await shot("07-chase-race");
  console.log("CAM", await page.evaluate(() => window.__dragBrasil.cameraMode));

  // results
  await page.waitForSelector("#results:not(.hidden)", { timeout: 45000 });
  await page.waitForTimeout(700);
  await shot("08-results");
  const result = await page.evaluate(() => ({
    title: document.getElementById("res-title").textContent,
    sub: document.getElementById("res-sub").textContent,
    et: document.getElementById("res-et").textContent,
    reaction: document.getElementById("res-reaction").textContent,
    trap: document.getElementById("res-speed").textContent,
    rival: document.getElementById("res-rival-et").textContent,
    money: document.getElementById("res-money").textContent,
    record: !document.getElementById("res-record").classList.contains("hidden"),
    save: {
      money: window.__dragBrasil.save.money,
      wins: window.__dragBrasil.save.wins,
      bestET: window.__dragBrasil.save.bestET,
    },
    playerFoul: window.__dragBrasil.foul,
    playerET: window.__dragBrasil.playerET,
    rivalET: window.__dragBrasil.rivalET,
  }));
  console.log("RESULT", JSON.stringify(result));

  await page.keyboard.up("ArrowUp");

  // back to menu and re-enter garage to confirm persistence in UI
  await page.click("#btn-res-menu");
  await page.waitForSelector("#menu:not(.hidden)");
  await page.waitForTimeout(500);
  const menuAfter = await page.evaluate(() => ({
    money: document.getElementById("menu-money").textContent,
    best: document.getElementById("menu-best").textContent,
    wins: document.getElementById("menu-wins").textContent,
    rival: document.getElementById("menu-rival").textContent,
  }));
  console.log("MENU AFTER", JSON.stringify(menuAfter));

  // mobile smoke test
  const mobile = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  const mp = await mobile.newPage();
  const merrors = [];
  mp.on("pageerror", (e) => merrors.push(e.message));
  await mp.goto(BASE, { waitUntil: "load", timeout: 45000 });
  await mp.waitForSelector("#btn-boot", { state: "visible" });
  await mp.click("#btn-boot");
  await mp.waitForSelector("#menu:not(.hidden)");
  await mp.waitForTimeout(900);
  await mp.screenshot({ path: join(OUT, "verify-09-mobile-menu.jpg"), type: "jpeg", quality: 78 });
  console.log("MOBILE", JSON.stringify({ errors: merrors, rotateHidden: await mp.evaluate(() => document.getElementById("rotate-hint").classList.contains("hidden")) }));
  await mobile.close();

  await page.waitForTimeout(300);
  console.log("PAGE ERRORS", JSON.stringify(errors));
  console.log("CONSOLE ERRORS", JSON.stringify(consoleErrors));
} catch (e) {
  console.error("VERIFY FAILED", e);
  await shot("99-failure").catch(() => {});
  process.exitCode = 1;
} finally {
  await browser.close().catch(() => {});
}

